import React, { useState, useRef, useEffect } from 'react';
import Member1 from '../Assets/Member1.png';
import { FaEdit, FaTrash } from 'react-icons/fa';
import Projectsedit from './Projectsedit';
import Projectcreate from './Projectcreate';

import warning from '../Assets/warning.png';

const dummyData = [
  {
    projectName: 'Smart Court System',
    startDate: '3 Jan 2022',
    dueDate: '13 May 2024',
    status: 'Process',
    projectManager: Member1,
    technicalManager: Member1
  },

];

const Projectstry = () => {
  const itemsPerPage = 5;
  const [currentPage, setCurrentPage] = useState(1);
  const [statusFilter, setStatusFilter] = useState('All');
  const [dropdownIndex, setDropdownIndex] = useState(null);
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [createModalOpen, setCreateModalOpen] = useState(false);

  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [selectedProject, setSelectedProject] = useState(null);
  const modalRef = useRef(null);

  const filteredData = statusFilter === 'All' ? dummyData : dummyData.filter(item => item.status === statusFilter);
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  const handlePreviousClick = () => {
    if (currentPage > 1) {
      setCurrentPage(currentPage - 1);
    }
  };

  const handleNextClick = () => {
    if (currentPage < totalPages) {
      setCurrentPage(currentPage + 1);
    }
  };

  const toggleDropdown = (index) => {
    setDropdownIndex(prevIndex => prevIndex === index ? null : index);
  };

  const openEditModal = (project) => {
    setSelectedProject(project);
    setEditModalOpen(true);
  };
  const openCreateModal = (project) => {
    setSelectedProject(project);
    setCreateModalOpen(true);
  };

  const openDeleteModal = (project) => {
    setSelectedProject(project);
    setDeleteModalOpen(true);
  };

  const closeEditModal = () => {
    setEditModalOpen(false);
  };
  const closeCreateModal = () => {
    setCreateModalOpen(false);
  };

  const closeDeleteModal = () => {
    setDeleteModalOpen(false);
  };

  const handleCancel = () => {
    closeDeleteModal();
  };


  const handleClickOutside = (event) => {
    if (!event.target.closest('.relative')) {
      setDropdownIndex(null); 
    }
    
    if (deleteModalOpen || editModalOpen|| createModalOpen) {
      if (!modalRef.current || !modalRef.current.contains(event.target)) {
        setDeleteModalOpen(false);
        setEditModalOpen(false);
        setCreateModalOpen(false);

      }
    }
  };

  useEffect(() => {
    document.addEventListener('click', handleClickOutside);
    return () => {
      document.removeEventListener('click', handleClickOutside);
    };
  }, []);

  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const visibleData = filteredData.slice(startIndex, endIndex);

  return (
    <div className="container" style={{ width: '900px', marginLeft: '0vw' }}>
      <div className="  flex flex-col px-5 max-w-[912px]">
        <div className="self-start ml-5 text-base font-bold text-blue-950 max-md:ml-2.5">
          Projects
        </div>
        <div className="flex gap-5 justify-between py-4 pl-4 mt-6 w-full text-xs bg-white max-md:flex-wrap max-md:pl-5 max-md:max-w-full">
          <div className="flex gap-3 my-auto font-medium whitespace-nowrap text-neutral-400">
            <div className={`cursor-pointer ${statusFilter === 'All' && 'font-bold text-blue-600'}`} onClick={() => setStatusFilter('All')}>All</div>
            <div className={`cursor-pointer ${statusFilter === 'Completed' && 'font-bold text-blue-600'}`} onClick={() => setStatusFilter('Completed')}>Completed</div>
            <div className={`cursor-pointer ${statusFilter === 'Process' && 'font-bold text-blue-600'}`} onClick={() => setStatusFilter('Process')}>Process</div>
            <div className={`cursor-pointer ${statusFilter === 'Canceled' && 'font-bold text-blue-600'}`} onClick={() => setStatusFilter('Canceled')}>Canceled</div>
          </div>
          <div className=" cursor-pointer flex gap-2 justify-center px-3 py-2 font-bold text-white bg-sky-500 rounded-md" onClick={() => setCreateModalOpen(true)}>
            +
            <div>Create New Project</div>
          </div>
        </div>
        <div className="flex gap-5 justify-center items-center py-3.5 pr-3.5 pl-10 text-xs font-bold text-black bg-white max-md:flex-wrap max-md:px-5">
          <div className="flex-1 self-stretch my-auto">Project Name</div>
          <div className="flex-1 self-stretch ml-32 my-auto text-center">Start Date</div>
          <div className="flex-1 self-stretch my-auto text-center">Due Date</div>
          <div className="flex-1 self-stretch my-auto text-center">Status</div>
          <div className="flex-1 self-stretch text-center">Project Manager</div>
          <div className="flex-1 self-stretch text-center">Technical Manager</div>
          <div className="flex-1 self-stretch my-auto text-center">Actions</div>
        </div>
        {visibleData.map((data, index) => (
          <div key={index} className="flex gap-5 justify-center items-center py-3.5 pr-3.5 pl-10 w-full bg-purple-50 max-md:flex-wrap max-md:px-5 max-md:max-w-full">
            <div className="flex gap-2 self-stretch">
              <div className="flex flex-col justify-center text-lg font-semibold text-white whitespace-nowrap">
                <div className="pl-2 bg-blue-600 rounded-sm h-[29px] w-[29px]">
                  S
                </div>
              </div>
              <div className=" w-32 my-auto text-xs font-medium text-black">
                {data.projectName}
              </div>
            </div>
            <div className="flex-1 ml-12 self-stretch my-auto text-xs font-medium text-black">
              {data.startDate}
            </div>
            <div className="flex-1 self-stretch my-auto text-xs font-medium text-center text-black">
              {data.dueDate}
            </div>
            <div className={` cursor-pointer w-20 px-3 py-2 mr-5 text-xs font-medium whitespace-nowrap rounded-2xl ${
              data.status === 'Completed' ? 'text-green-600 bg-emerald-50' :
              data.status === 'Process' ? 'text-orange-600 bg-orange-50' :
              data.status === 'Canceled' ? 'text-red-600 bg-red-50' :
              ''}`}>
              {data.status}
            </div>
            <img loading="lazy" src={data.projectManager} alt='' className=" cursor-pointer shrink-0 mr-10 rounded-full border-sky-500 border-solid" />
            <img loading="lazy" src={data.technicalManager} alt='' className="cursor-pointer shrink-0 mr-14 rounded-full border-sky-500 border-solid" />
            
            <div className="relative flex gap-2">
              <div className="mr-10 self-stretch cursor-pointer text-sm font-extrabold tracking-tighter text-slate-900" onClick={() => toggleDropdown(index)}>. . .</div>
              {dropdownIndex === index && (
                <div className="absolute z-10 flex flex-row mr-3 mt-4 gap-1.5 bg-white border-gray-300 rounded shadow-md py-1 px-2">
                  <FaEdit className="cursor-pointer text-green-500" onClick={() => openEditModal(data)} />
                  <FaTrash className="cursor-pointer text-red-500" onClick={() => openDeleteModal(data)} /> 
                </div>
              )}
            </div>
          </div>
        ))}
        <div className="flex justify-center items-center p-3.5 w-full text-xs font-medium whitespace-nowrap bg-white text-neutral-400 max-md:px-5 max-md:max-w-full">
          <div className="flex gap-2.5 justify-between">
            <div className="my-auto" onClick={handlePreviousClick} style={{ cursor: currentPage > 1 ? 'pointer' : 'not-allowed', opacity: currentPage === 1 ? 0.5 : 1 }}>Previous</div>
            {[...Array(totalPages)].map((_, page) => (
              <div
                key={page}
                className={`justify-center items-center px-2 py-2 w-7 h-7 text-center text-${currentPage === page + 1 ? 'white bg-sky-500' : 'black bg-neutral-200'} rounded`}
                onClick={() => setCurrentPage(page + 1)}
                style={{ cursor: 'pointer' }}
              >
                {page + 1}
              </div>
            ))}
            <div className="my-auto" onClick={handleNextClick} style={{ cursor: currentPage < totalPages ? 'pointer' : 'not-allowed', opacity: currentPage === totalPages ? 0.5 : 1 }}>Next</div>
          </div>
        </div>
      </div>
      {editModalOpen && (
         <div className="fixed top-0 left-0 w-full h-full z-50 flex items-center justify-center bg-gray-800 bg-opacity-50">
         
         <div ref={modalRef} className="bg-white w-2/3 p-8 rounded-md relative">
         <span className="absolute top-4 right-8 cursor-pointer text-gray-500" onClick={closeEditModal}>X</span>

        <Projectsedit onClose={closeEditModal}>
        </Projectsedit> </div></div>
      )}
       {createModalOpen && (
         <div className="fixed top-0 left-0 w-full h-full z-50 flex items-center justify-center bg-gray-800 bg-opacity-50">
         
         <div ref={modalRef} className="bg-white w-2/3 p-8 rounded-md relative">
         <span className="absolute top-4 right-8 cursor-pointer text-gray-500" onClick={closeCreateModal}>X</span>

        <Projectcreate onClose={closeCreateModal}>
        </Projectcreate> </div></div>
      )}
      {deleteModalOpen && (
        <div className="fixed top-0 left-0 w-full h-full z-50 flex items-center justify-center bg-gray-800 bg-opacity-50">
          <div ref={modalRef} className="bg-white w-1/2 p-8 rounded-md relative">
            <span className="absolute top-4 right-8 cursor-pointer text-gray-500" onClick={closeDeleteModal}>X</span>
            <div className="flex flex-col items-center justify-center">
              <div className="flex gap-2 self-start mt-2.5 text-2xl font-bold text-blue-950">
                <img
                  src={warning}
                  className="w-8"
                  alt=""
                />
                <div className="justify-center py-0.5">Move to trash?</div>
              </div>
              <div className="mt-6 text-lg tracking-normal leading-6 text-justify text-zinc-500 max-md:max-w-full">
                Are you sure you want to move this project to trash?
                <br />
                <br />
                Only admins and project managers can restore the project from trash.
              </div>
              <div className="flex gap-5 justify-between self-end ml-10 mt-6 text-base">
                <div className="my-auto cursor-pointer text-black" onClick={handleCancel}>Cancel</div>
                <div className="cursor-pointer justify-center p-2.5 font-bold text-white bg-red-600 rounded-lg" onClick={() => console.log("Move to trash")}>
                  Move to trash
                </div>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Projectstry;
