import React from "react";
import apiService from "../services/apiServices";

const ResetPassword = () => {
  const [password, setPassword] = React.useState("");
  const [confirmPassword, setConfirmPassword] = React.useState("");
  const [showPassword, setShowPassword] = React.useState(false);

  const handlePasswordChange = (e) => {
    setPassword(e.target.value);
  };

  const handleConfirmPasswordChange = (e) => {
    setConfirmPassword(e.target.value);
  };

  const togglePasswordVisibility = () => {
    setShowPassword((prevShowPassword) => !prevShowPassword);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (password !== confirmPassword) {
      console.error("Passwords do not match");
      return;
    }
    
    try {
      const response = await apiService.resetPassword(password, confirmPassword);
      console.log(response); 
    } catch (error) {
      console.error("Error resetting password:", error);
    }
  };


  return (
<div className="flex flex-col items-center p-20  rounded-2xl shadow-sm max-w-[540px] max-md:px-5" style={{ marginLeft: '700px' }}>
      <div className="mt-4 text-3xl font-semibold text-blue-950">EAII-PMS</div>
      <div className="mt-5 text-2xl font-semibold text-blue-950">
        New Password
      </div>
      <div className="mt-5 text-base tracking-normal leading-6 text-center text-zinc-500">
        Set a new password for your account.
      </div>
      <form onSubmit={handleSubmit} className="w-full mt-9">
        <div className="text-base text-slate-950">New Password</div>
        <div className="relative mt-3 max-w-full ">
          <input
            type={showPassword ? "text" : "password"}
            value={password}
            onChange={handlePasswordChange}
            placeholder="Enter your new password"
            className="justify-center items-start px-4 py-5 mt-3 max-w-full text-sm whitespace-nowrap rounded-lg bg-zinc-100 text-slate-950 max-md:pr-14" // Adjusted padding for the eye icon
            required
          />
          <button
            type="button"
            onClick={togglePasswordVisibility}
            className=" inset-y-0 right-0 px-3 py-1.5 my-auto text-blue-950 flex items-center"
          >
          </button>
        </div>
        <div className="text-base text-slate-950 mt-5">Confirm New Password</div>
        <div className="relative mt-3 max-w-full">
          <input
            type={showPassword ? "text" : "password"}
            value={confirmPassword}
            onChange={handleConfirmPasswordChange}
            placeholder="Confirm your new password"
            className="justify-center items-start px-4 py-5 mt-3 max-w-full text-sm whitespace-nowrap rounded-lg bg-zinc-100 text-slate-950 max-md:pr-14" // Adjusted padding for the eye icon
            required
          />
          <button
            type="button"
            onClick={togglePasswordVisibility}
            className="inset-y-0 right-0 py-1.5 my-auto relative text-blue-950 flex items-center border-l border-gray-300"
            >
          </button>
        </div>
        <button
          type="submit"
          className="justify-center items-center px-16 py-4 mt-8 max-w-full text-base font-bold text-white bg-sky-500 rounded-xl w-[349px] max-md:px-5"
        >
          Update Password
        </button>
      </form>
    </div>
  );
};

export default ResetPassword;
