import React, { useEffect, useState } from "react";
import Createnewproject from "./Projectcreate";
import "./Projects.css";

const Projects = (props) => {
  const projectsData = [
    {
      name: "Project 1",
      dueDate: "2024-03-01",
      startDate: "2020-03-01",
      status: "Completed",
      projmanager: "Leader",
      technicalManager: "Leader",
      members: ["Member1", "Leader", "Member1"],
    },
    {
      name: "Project 2",
      dueDate: "2024-03-01",
      startDate: "2024-03-01",
      status: "Process",
      projmanager: "Member1",
      technicalManager: "Leader",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "Project 3",
      dueDate: "2024-03-01",
      startDate: "2020-03-01",

      status: "Canceled",
      projmanager: "Leader",
      technicalManager: "Member1",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "Project 4",
      dueDate: "2024-03-01",
      startDate: "2024-01-01",
      status: "Canceled",
      projmanager: "Member1",
      technicalManager: "Leader",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "Hoject 5",
      dueDate: "2024-03-01",
      startDate: "2024-02-01",
      status: "Process",
      projmanager: "Member1",
      technicalManager: "Member1",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "apbc 6",
      dueDate: "2024-03-01",
      startDate: "2024-03-01",

      status: "Process",
      projmanager: "Leader",
      technicalManager: "Member1",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "Hoject 5",
      dueDate: "2024-03-01",
      startDate: "2019-03-01",

      status: "Process",
      projmanager: "Member1",
      technicalManager: "Member1",
      members: ["Member1", "Member1", "Leader"],
    },
    {
      name: "Hoject 5",
      dueDate: "2024-03-01",
      startDate: "2018-03-01",

      status: "Process",
      projmanager: "Member1",
      technicalManager: "Member1",
      members: ["Member1", "Member1", "Leader"],
    },
  ];

  const itemsPerPage = 6;

  const [currentPage, setCurrentPage] = useState(1);
  const [selectedStatus, setSelectedStatus] = useState("All");
  const [showCreateProjectContainer, setShowCreateProjectContainer] =
    useState(false);

  const handleStatusFilter = (status) => {
    setSelectedStatus(status);
    setCurrentPage(1);
  };

  const handleCreateProject = () => {
    setShowCreateProjectContainer(true);
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handlePreviousPage = () => {
    setCurrentPage((prevPage) => Math.max(prevPage - 1, 1));
  };

  const handleNextPage = () => {
    setCurrentPage((prevPage) => Math.min(prevPage + 1, totalPages));
  };

  const handleCloseModal = () => {
    setShowCreateProjectContainer(false);
  };

  const filteredProjects =
    selectedStatus === "All"
      ? projectsData
      : projectsData.filter(
          (project) =>
            project.status.toLowerCase() === selectedStatus.toLowerCase()
        );

  const totalPages = Math.ceil(filteredProjects.length / itemsPerPage);

  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = Math.min(startIndex + itemsPerPage, filteredProjects.length);

  const displayedProjects = filteredProjects.slice(startIndex, endIndex);

  const getColorByRange = (value) => {
    if (!value) return "black";

    const colorRanges = [
      { range: ["a".charCodeAt(0), "e".charCodeAt(0)], color: "red" },
      { range: ["f".charCodeAt(0), "j".charCodeAt(0)], color: "green" },
      { range: ["k".charCodeAt(0), "o".charCodeAt(0)], color: "purple" },
      { range: ["p".charCodeAt(0), "t".charCodeAt(0)], color: "blue" },
      { range: ["u".charCodeAt(0), "z".charCodeAt(0)], color: "gray" },
    ];
    const charCode = value.toLowerCase().charCodeAt(0);
    const rangeMatch = colorRanges.find(
      (range) => charCode >= range.range[0] && charCode <= range.range[1]
    );
    return rangeMatch ? rangeMatch.color : "";
  };

  useEffect(() => {
    const handleClickOutsideModal = (event) => {
      const modal = document.querySelector(".create-project-container");
      if (modal && !modal.contains(event.target)) {
        handleCloseModal();
      }
    };

    document.addEventListener("mousedown", handleClickOutsideModal);

    return () => {
      document.removeEventListener("mousedown", handleClickOutsideModal);
    };
  }, []);
  return (
    <div>
      <div className="proj-title">Projects</div>
      <div className="status-filter">
        <span
          className={selectedStatus === "All" ? "active-filter" : ""}
          onClick={() => handleStatusFilter("All")}
        >
          All
        </span>
        <span
          className={selectedStatus === "Completed" ? "active-filter" : ""}
          onClick={() => handleStatusFilter("Completed")}
        >
          Completed
        </span>
        <span
          className={selectedStatus === "Process" ? "active-filter" : ""}
          onClick={() => handleStatusFilter("Process")}
        >
          Process
        </span>
        <span
          className={selectedStatus === "Canceled" ? "active-filter" : ""}
          onClick={() => handleStatusFilter("Canceled")}
        >
          Canceled
        </span>
        <button
          className="create-project-button"
          onClick={() => handleCreateProject()}
        >
          + Create New Project
        </button>
      </div>

      <div className="proj">
        <table class="hoverTable">
          <thead>
            <tr>
              <th>Project Name</th>
              <th>Start Date</th>
              <th>End Date</th>
              <th className="project_status">Status</th>
              <th>Project Manager</th>
              <th>Technical Manager</th>
              <th>Members</th>
            </tr>
          </thead>
          <tbody>
            {displayedProjects.map((project, index) => (
              <tr
                class="clickable-row"
                key={index}
                onClick={() => {
                  props.setIsProjectSelected(true);
                }}
              >
                <td>
                  <span
                    className="initials"
                    style={{
                      backgroundColor: getColorByRange(project.name.charAt(0)),
                    }}
                  >
                    {project.name.charAt(0).toUpperCase()}
                  </span>
                  {project.name}
                </td>
                <td>{project.startDate}</td>
                <td>{project.dueDate}</td>
                <td className="project_status">
                  {project.status === "Completed" && (
                    <span className="completed">Completed</span>
                  )}
                  {project.status === "Canceled" && (
                    <span className="canceled">Canceled</span>
                  )}
                  {project.status === "Process" && (
                    <span className="process">Process</span>
                  )}
                </td>
                <td>
                  <img
                    src={require(`../Assets/${project.projmanager}.png`)}
                    alt="Project Manager"
                    className="project-manager"
                  />
                </td>
                <td>
                  <img
                    src={require(`../Assets/${project.technicalManager}.png`)}
                    alt="Technical Manager"
                    className="technical-manager"
                  />
                </td>
                <td className="members-container">
                  {project.members.map((member, memberIndex) => (
                    <img
                      key={memberIndex}
                      src={require(`../Assets/${member}.png`)}
                      alt={`Member ${memberIndex + 1}`}
                      className="members-image"
                    />
                  ))}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="pagination">
        <button className="prev-button" onClick={handlePreviousPage}>
          {" "}
          Previous
        </button>
        {Array.from({ length: totalPages }, (_, index) => (
          <span
            key={index + 1}
            className={currentPage === index + 1 ? "active-page" : ""}
            onClick={() => handlePageChange(index + 1)}
          >
            {index + 1}
          </span>
        ))}
        <button className="next-button" onClick={handleNextPage}>
          Next
        </button>
      </div>

      {showCreateProjectContainer && (
        <div className="modal-overlay">
          <div className="create-project-container">
            <div className="modal">
              <button className="close-modal" onClick={handleCloseModal}>
                X
              </button>
              <Createnewproject />
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Projects;
