import { InputAdornment, TextField } from "@mui/material";
import Backdrop from "@mui/material/Backdrop";
import { BarChart } from "@mui/x-charts/BarChart";
import React, { useEffect, useState } from "react";
import PuffLoader from "react-spinners/PuffLoader";
import apiService from "../services/apiServices";

import "./Home.css";
//icons
import TaskIcon from "@mui/icons-material/Checklist";
import ActivityIcon from "@mui/icons-material/ListAlt";
import SubTaskIcon from "@mui/icons-material/Splitscreen";
import ProgressBar from "@ramonak/react-progress-bar";

import Container from "@mui/material/Container";
import "react-dropdown/style.css";

// Table
import FirstPageIcon from "@mui/icons-material/FirstPage";
import KeyboardArrowLeft from "@mui/icons-material/KeyboardArrowLeft";
import KeyboardArrowRight from "@mui/icons-material/KeyboardArrowRight";
import LastPageIcon from "@mui/icons-material/LastPage";
import Box from "@mui/material/Box";
import IconButton from "@mui/material/IconButton";
import Paper from "@mui/material/Paper";
import Table from "@mui/material/Table";
import TableBody from "@mui/material/TableBody";
import TableCell, { tableCellClasses } from "@mui/material/TableCell";
import TableContainer from "@mui/material/TableContainer";
import TableFooter from "@mui/material/TableFooter";
import TableHead from "@mui/material/TableHead";
import TablePagination from "@mui/material/TablePagination";
import TableRow from "@mui/material/TableRow";
import { styled, useTheme } from "@mui/material/styles";
import PropTypes from "prop-types";

//Charts
import { PieChart } from "@mui/x-charts/PieChart";

//

import SearchIcon from "@mui/icons-material/Search";

import { Typography } from "@material-ui/core";
import {
  ArcElement,
  BarController,
  BarElement,
  CategoryScale,
  Chart as ChartJS,
  Legend,
  LinearScale,
  Title,
  Tooltip,
} from "chart.js";

ChartJS.register(
  Title,
  Tooltip,
  Legend,
  ArcElement,
  CategoryScale,
  LinearScale,
  BarElement,
  BarController
);
const projectOptions = [
  "Smart Court System",
  "Police Commission System",
  "Project Managment System",
  "User Managment System",
  "Customs Commision System",
  "Planning and Monitoring",
];

function TablePaginationActions(props) {
  const theme = useTheme();
  const { count, page, rowsPerPage, onPageChange } = props;

  const handleFirstPageButtonClick = (event) => {
    onPageChange(event, 0);
  };

  const handleBackButtonClick = (event) => {
    onPageChange(event, page - 1);
  };

  const handleNextButtonClick = (event) => {
    onPageChange(event, page + 1);
  };

  const handleLastPageButtonClick = (event) => {
    onPageChange(event, Math.max(0, Math.ceil(count / rowsPerPage) - 1));
  };

  return (
    <Box sx={{ flexShrink: 0, ml: 2.5 }}>
      <IconButton
        onClick={handleFirstPageButtonClick}
        disabled={page === 0}
        aria-label="first page"
      >
        {theme.direction === "rtl" ? <LastPageIcon /> : <FirstPageIcon />}
      </IconButton>
      <IconButton
        onClick={handleBackButtonClick}
        disabled={page === 0}
        aria-label="previous page"
      >
        {theme.direction === "rtl" ? (
          <KeyboardArrowRight />
        ) : (
          <KeyboardArrowLeft />
        )}
      </IconButton>
      <IconButton
        onClick={handleNextButtonClick}
        disabled={page >= Math.ceil(count / rowsPerPage) - 1}
        aria-label="next page"
      >
        {theme.direction === "rtl" ? (
          <KeyboardArrowLeft />
        ) : (
          <KeyboardArrowRight />
        )}
      </IconButton>
      <IconButton
        onClick={handleLastPageButtonClick}
        disabled={page >= Math.ceil(count / rowsPerPage) - 1}
        aria-label="last page"
      >
        {theme.direction === "rtl" ? <FirstPageIcon /> : <LastPageIcon />}
      </IconButton>
    </Box>
  );
}

TablePaginationActions.propTypes = {
  count: PropTypes.number.isRequired,
  onPageChange: PropTypes.func.isRequired,
  page: PropTypes.number.isRequired,
  rowsPerPage: PropTypes.number.isRequired,
};

const Dashboard = (props) => {
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [selectedProject, setSelectedProject] = useState();

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };
  const [loading, setLoading] = useState(false);

  const [userInfo, setUserInfo] = useState(() => {
    return JSON.parse(localStorage.getItem("userInfo")) || [];
  });
  const [activities, setActivities] = useState([]);
  const [activityLength, setActivityLength] = useState();
  const [tasks, setTasks] = useState([]);
  const [subTasks, setSubTasks] = useState([]);
  const [totalTasks, setTotalTasks] = useState();
  const [totalSubTasks, setTotalSubTasks] = useState();
  const [completedTasks, setCompletedTasks] = useState([]);
  const [onProgressTasks, setOnProgressTasks] = useState([]);
  const [pendingTask, setPendingTasks] = useState([]);

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  function createData(name, calories, fat, carbs, protein) {
    return { name, calories, fat, carbs, protein };
  }
  const data2 = [
    { label: "Total Completed", value: completedTasks.length, color: "green" },
    {
      label: "Total In Progress",
      value: onProgressTasks.length,
      color: "#FFA500",
    },
    {
      label: "Total Pending",
      value: pendingTask.length,
      color: "#808080",
    },
  ];

  const fetchActivities = async () => {
    try {
      setLoading(true);
      let activityData = await apiService.getAllActivities(
        props.setSelectedProjectInfo.project_id,
        userInfo.access_token
      );
      const sortedResponse = activityData.sort((a, b) => {
        if (a.activity.createdAt > b.activity.createdAt) {
          return -1;
        }
      });
      console.log(sortedResponse);
      setTimeout(() => {
        setActivities(sortedResponse);

        let all_tasks = [];

        for (const activity of sortedResponse) {
          const task = activity.tasks;
          if (task.length === 0) {
            continue;
          }
          all_tasks.push(...task);
        }
        setTasks(all_tasks);
        const completed_task = all_tasks.filter(
          (data) => data.task_status === "Completed"
        );

        setCompletedTasks(completed_task);
        const on_progress_task = all_tasks.filter(
          (data) => data.task_status === "In Progress"
        );

        setOnProgressTasks(on_progress_task);

        const pending_task = all_tasks.filter(
          (data) => data.task_status === "Pending"
        );

        setPendingTasks(pending_task);

        setActivityLength(sortedResponse.length);
        setTotalTasks(
          sortedResponse.reduce((n, { Tasklength }) => n + Tasklength, 0)
        );
        setTotalSubTasks(
          sortedResponse.reduce(
            (n, { sub_tasks_length }) => n + sub_tasks_length,
            0
          )
        );
        setLoading(false);
      }, 1500);
    } catch (error) {
      console.error("Error fetching activity:", error);
    }
  };

  const [searchTerm, setSearchTerm] = useState("");

  const StyledTableCell = styled(TableCell)(({ theme }) => ({
    [`&.${tableCellClasses.head}`]: {
      fontSize: 15,
    },
    [`&.${tableCellClasses.body}`]: {
      fontSize: 14,
    },
  }));

  const StyledTableRow = styled(TableRow)(({ theme }) => ({
    "&:nth-of-type(odd)": {
      backgroundColor: theme.palette.action.hover,
    },
    // hide last border
    "&:last-child td, &:last-child th": {
      border: 0,
    },
  }));

  const getColorByRange = (value) => {
    if (!value) return "black";

    const colorRanges = [
      { range: ["a".charCodeAt(0), "e".charCodeAt(0)], color: "red" },
      { range: ["f".charCodeAt(0), "j".charCodeAt(0)], color: "green" },
      { range: ["k".charCodeAt(0), "o".charCodeAt(0)], color: "purple" },
      { range: ["p".charCodeAt(0), "t".charCodeAt(0)], color: "blue" },
      { range: ["u".charCodeAt(0), "z".charCodeAt(0)], color: "gray" },
    ];
    const charCode = value.toLowerCase().charCodeAt(0);
    const rangeMatch = colorRanges.find(
      (range) => charCode >= range.range[0] && charCode <= range.range[1]
    );
    return rangeMatch ? rangeMatch.color : "";
  };
  useEffect(() => {
    async function fetchUsers() {
      localStorage.setItem("userInfo", JSON.stringify(userInfo));
    }
    fetchUsers();
    fetchActivities();
  }, [userInfo]);
  return (
    <div className="ml-auto w-4/5 mr-5 mt-24 relative">
      <Backdrop
        sx={{ color: "#fff", zIndex: (theme) => theme.zIndex.drawer + 1 }}
        open={loading}
      >
        <PuffLoader color="#fff" />
      </Backdrop>
      <Container maxWidth="lg">
        <box
          class="flex flex-wrap my-6 justify-evenly"
          style={{ marginTop: "8%" }}
        >
          <a
            href="#"
            class="flex flex-row gap-4 items-center max-w-full py-2 pr-40 pl-5 bg-sky-950 border-gray-200 rounded-lg shadow  dark:bg-gray-800 dark:border-gray-700 dark:hover:bg-gray-700"
          >
            <div class="text-white ">
              <ActivityIcon fontSize="large" />
            </div>
            <div class="space-y-0">
              <h5 class="text-base tracking-tight text-white dark:text-white">
                Total Activities
              </h5>
              <p class="font-normal text-white dark:text-gray-400">
                {activityLength}
              </p>
            </div>
          </a>

          <a
            href="#"
            class="flex flex-row gap-4 items-center max-w-xs pr-40 pl-5 bg-sky-950 border-gray-200 rounded-lg shadow  dark:bg-gray-800 dark:border-gray-700 dark:hover:bg-gray-700"
          >
            <div class="text-white">
              <TaskIcon fontSize="large" />
            </div>
            <div class="space-y-0">
              <h5 class=" text-base tracking-tight text-white dark:text-white">
                Total Tasks
              </h5>
              <p class="font-normal text-white dark:text-gray-400">
                {totalTasks}
              </p>
            </div>
          </a>

          <a
            href="#"
            class="flex flex-row gap-4 items-center max-w-xs pr-40 pl-5 bg-sky-950 border-gray-200 rounded-lg shadow  dark:bg-gray-800 dark:border-gray-700 dark:hover:bg-gray-700"
          >
            <div class="text-white">
              <SubTaskIcon fontSize="large" />
            </div>
            <div class="space-y-0">
              <h5 class="text-base tracking-tight text-white dark:text-white">
                Total Sub Tasks
              </h5>
              <p class="font-normal text-white dark:text-gray-400">
                {totalSubTasks}
              </p>
            </div>
          </a>
        </box>

        <box class="shadow-3xl my-10 rounded-lg border-t-2 ">
          {" "}
          <div style={{ backgroundColor: "#f7f6fe" }}>
            <div className="flex flex-wrap items-center justify-between text-center gap-28">
              <text class="p-5 text-2xl font-bold text-sky-950">
                {props.setSelectedProjectInfo.name}
              </text>

              <div class=" self-center ">
                <TextField
                  type="text"
                  placeholder="Search Task"
                  size="small"
                  class="bg-white rounded-lg"
                  variant="outlined"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  InputProps={{
                    startAdornment: (
                      <InputAdornment position="start">
                        <SearchIcon />
                      </InputAdornment>
                    ),
                  }}
                />
              </div>
            </div>
          </div>
        </box>

        <box class="shadow-3xl lg:flex border-x-2 border-b-2">
          {" "}
          <div style={{ backgroundColor: "#f7f6fe" }} class="content-center">
            <div className="flex flex-wrap gap-18">
              <div className="flex flex-col space-y-10 p-5">
                <div className="text-center space-y-5">
                  <p className="text-3xl font-medium font-sans">{totalTasks}</p>
                  <p className="text-xl font-medium font-sans">Project Tasks</p>
                </div>
                <div className="text-center space-y-5">
                  <p className="text-3xl font-medium font-sans">
                    {completedTasks.length}
                  </p>
                  <p className="text-xl font-medium font-sans">
                    Completed Tasks
                  </p>
                </div>
                <div className="text-center space-y-5">
                  <p className="text-3xl font-medium font-sans">
                    {onProgressTasks.length}
                  </p>
                  <p className="text-xl font-medium font-sans">
                    On Progress Sub Tasks
                  </p>
                </div>
              </div>{" "}
            </div>
          </div>
          <div
            class="rounded-lg lg:py-16 lg:pr-20 "
            style={{ backgroundColor: "#f7f6fe" }}
          >
            <TableContainer
              component={Paper}
              sx={{
                maxHeight: 400,
                width: "100%",
                border: 0.5,
                borderRadius: 3,
                borderColor: "#c7c7c7",
              }}
            >
              <Table
                sx={{
                  minWidth: 900,
                  minHeight: 390,
                  [`& .${tableCellClasses.root}`]: {
                    borderBottom: "none",
                  },
                }}
                stickyHeader
                size="large"
              >
                {totalTasks !== 0 ? (
                  <>
                    <TableHead>
                      <TableRow>
                        <StyledTableCell>Task Name</StyledTableCell>
                        <StyledTableCell>Task Due Date</StyledTableCell>
                        <StyledTableCell>Completion</StyledTableCell>
                        <StyledTableCell>Status</StyledTableCell>
                      </TableRow>
                    </TableHead>

                    <TableBody stripedRows>
                      {(rowsPerPage > 0
                        ? tasks.slice(
                            page * rowsPerPage,
                            page * rowsPerPage + rowsPerPage
                          )
                        : tasks
                      ).map((data, index) => {
                        {
                          const progress = function (start_date, end_date) {
                            const currentDate = new Date();
                            const totalDuration =
                              new Date(end_date) - new Date(start_date);
                            const elapsedDuration =
                              currentDate - new Date(start_date);
                            const progress = Math.min(
                              Math.max(
                                (elapsedDuration / totalDuration) * 100,
                                0
                              ),
                              100
                            );
                            return progress;
                          };
                          const tasks = data;

                          const progress_result = progress(
                            tasks.start_date,
                            tasks.end_date
                          );

                          return (
                            <StyledTableRow
                              class="clickable-row"
                              style={
                                index % 2
                                  ? { background: "white" }
                                  : { background: "#f7f6fe" }
                              }
                            >
                              <StyledTableCell component="th" scope="row">
                                <span
                                  className="initials"
                                  style={{
                                    backgroundColor: getColorByRange(
                                      tasks.name
                                    ),
                                  }}
                                >
                                  {tasks.name.charAt(0).toUpperCase()}
                                </span>
                                {tasks.name}
                              </StyledTableCell>
                              <StyledTableCell>
                                {new Date(tasks.end_date).toLocaleDateString()}
                              </StyledTableCell>
                              <StyledTableCell>
                                <div class="mx-5">
                                  <ProgressBar
                                    completed={parseInt(progress_result)}
                                    bgColor={`${
                                      parseInt(progress_result) < 75
                                        ? "orange"
                                        : parseInt(progress_result) <= 100 &&
                                          tasks.task_status === "Completed"
                                        ? "green"
                                        : parseInt(progress_result) <= 100 &&
                                          tasks.task_status !== "Completed"
                                        ? "#A52A2A"
                                        : "blue"
                                    }`}
                                    borderRadius="5px"
                                  />
                                </div>
                              </StyledTableCell>

                              <StyledTableCell>
                                {tasks.task_status}
                              </StyledTableCell>
                            </StyledTableRow>
                          );
                        }
                      })}
                    </TableBody>

                    <TableFooter>
                      <TableRow>
                        <TablePagination
                          rowsPerPageOptions={[
                            5,
                            10,
                            25,
                            { label: "All", value: -1 },
                          ]}
                          colSpan={3}
                          count={tasks.length}
                          rowsPerPage={rowsPerPage}
                          page={page}
                          slotProps={{
                            select: {
                              inputProps: {
                                "aria-label": "rows per page",
                              },
                              native: true,
                            },
                          }}
                          onPageChange={handleChangePage}
                          onRowsPerPageChange={handleChangeRowsPerPage}
                          ActionsComponent={TablePaginationActions}
                        />
                      </TableRow>
                    </TableFooter>
                  </>
                ) : (
                  <Typography className="text-center self-center">
                    No Task Data
                  </Typography>
                )}
              </Table>
            </TableContainer>
          </div>
        </box>

        <box class="lg:flex lg:flex-wrap lg:gap-5 lg:my-12 lg:rounded-lg ">
          <div className="shadow-lg max-w-3xl grow border-x-2 border-y-2 rounded-lg">
            <div className="flex flex-wrap justify-between items-center py-5 gap-10">
              <text class="px-5 text-xl font-bold text-sky-950 font-sans">
                Activity
              </text>
            </div>

            <box class="shadow-3xl my-10 rounded-lg">
              {" "}
              <div>
                <div>
                  {activities.length !== 0 ? (
                    <BarChart
                      series={[
                        {
                          data: activities.map((data) => {
                            const progress = function (start_date, end_date) {
                              const currentDate = new Date();
                              const totalDuration =
                                new Date(end_date) - new Date(start_date);
                              const elapsedDuration =
                                currentDate - new Date(start_date);
                              const progress = Math.min(
                                Math.max(
                                  (elapsedDuration / totalDuration) * 100,
                                  0
                                ),
                                100
                              );
                              return progress;
                            };

                            const activity = data.activity;

                            const progress_result = progress(
                              activity.start_date,
                              activity.end_date
                            );

                            return parseInt(progress_result);
                          }),
                          stack: "A",
                          // label: "Activities",
                          color: activities.map((data) => {
                            const progress = function (start_date, end_date) {
                              const currentDate = new Date();
                              const totalDuration =
                                new Date(end_date) - new Date(start_date);
                              const elapsedDuration =
                                currentDate - new Date(start_date);
                              const progress = Math.min(
                                Math.max(
                                  (elapsedDuration / totalDuration) * 100,
                                  0
                                ),
                                100
                              );
                              return progress;
                            };

                            const activity = data.activity;

                            const progress_result = progress(
                              activity.start_date,
                              activity.end_date
                            );

                            let color_check = "gray";

                            return color_check;
                          }),
                        },
                      ]}
                      // width={600}
                      height={320}
                      xAxis={[
                        {
                          data: activities.map((data, index) => index + 1),
                          scaleType: "band",
                        },
                      ]}
                      margin={{ top: 50, bottom: 30, left: 40, right: 10 }}
                    />
                  ) : (
                    <Typography className="text-center">
                      No Activity Data
                    </Typography>
                  )}
                </div>
              </div>
            </box>
          </div>
          <div className="shadow-lg shrink grow border-x-2 border-y-2 rounded-lg max-w-lg">
            <div class="pt-10 pb-4 px-5 text-lg font-bold text-sky-950">
              Project Statistics
            </div>
            <div>
              {tasks.length !== 0 ? (
                <PieChart
                  margin={{ bottom: 100, left: 100, right: 100 }}
                  series={[
                    {
                      data: data2,
                      innerRadius: 60,
                      outerRadius: 80,
                    },
                  ]}
                  height={300}
                  width={350}
                  slotProps={{
                    legend: {
                      direction: "column",
                      position: { vertical: "bottom", horizontal: "middle" },
                      padding: 0,
                    },
                  }}
                  bgColor={`green`}
                />
              ) : (
                <Typography className="text-center">No Task Data</Typography>
              )}
            </div>
          </div>
        </box>
      </Container>
    </div>
  );
};

export default Dashboard;
