import React, { useEffect, useState } from "react";
import apiService from "../services/apiServices";

const RoleView = (props) => {
  const [roleName, setRoleName] = useState("");
  const [permissions, setPermissions] = useState([]);
  const [rolePermission, setRolePermission] = useState([]);

  useEffect(() => {
    const fetchRoleData = async () => {
      try {
        const permissionsResponse = await apiService.getSpecificRolePermission(
          props.id.role_id
        );
        setPermissions(permissionsResponse.Permissions);
        setRoleName(permissionsResponse.name);
        setRolePermission(permissionsResponse.Permissions); // Update rolePermission state
      } catch (error) {
        console.error("Error fetching role data:", error);
      }
    };

    fetchRoleData();
  }, []);

  const groupedPermissions = rolePermission.reduce((acc, permission) => {
    const groupCode = permission.group_code;
    if (!acc[groupCode]) {
      acc[groupCode] = [];
    }
    acc[groupCode].push(permission);
    return acc;
  }, {});

  const renderPermissions = Object.entries(groupedPermissions)
    .reduce((rows, [groupCode, permissions], index) => {
      if (index % 4 === 0) {
        rows.push([]);
      }
      rows[rows.length - 1].push(
        <div key={groupCode} className="w-1/4">
          <div className="text-blue-900 text-xl mb-2 mx-5">
            <strong>
              {groupCode === "1" && "Organization"}
              {groupCode === "2" && "Member"}
              {groupCode === "3" && "Project"}
              {groupCode === "4" && "Activity"}
              {groupCode === "5" && "Task"}
              {groupCode === "6" && "Subtask"}
              {groupCode === "7" && "Team"}
              {groupCode === "8" && "Dashboard"}
              {groupCode === "9" && "Trash"}
              {groupCode === "10" && "Milestone"}


            </strong>
          </div>
          <div className="">
            <div className="">
              <ul className="list-disc pl-3">
                {permissions.map((permiss) => (
                  <li className="ml-3 mr-3 my-2" key={permiss.permission_id}>
                    <span>
                      <p>{permiss.name}</p>
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      );
      return rows;
    }, [])
    .map((row, index) => (
      <div key={index} className="flex">
        {row}
      </div>
    ));

  const emptyPlaceholders = Array(
    Math.ceil(Object.keys(groupedPermissions).length / 4) * 4 -
      Object.keys(groupedPermissions).length
  )
    .fill(null)
    .map((_, index) => <div key={index} className="w-1/4" />);

  return (
    <div className="mx-10 h-96 mb-5 overflow-y-auto">
      <div
        className="mb-4 text-3xl font-bold font-poppins"
        style={{ color: "#172B4D" }}
      >
        {roleName.charAt(0).toUpperCase() + roleName.slice(1)}
      </div>

      <div
        className="text-xl font-bold font-poppins mb-5 "
        style={{ color: "#172B4D" }}
      >
        Permissions
      </div>
      {renderPermissions}
      <div className="flex">{emptyPlaceholders}</div>
    </div>
  );
};

export default RoleView;
