import React, { useState, useEffect } from 'react';
import './Roles.css';
import SearchIcon from '../Assets/Search-icon.png';
import RoleView from './RoleView';
import RoleEdit from './RoleEdit';

import RoleAdd from './RoleAdd';

const Roles = () => {
  const rolesData = [
    {
      no: '1',
      name: 'Starting Committee',
      creationdate: '10/12/2020',
    },
    {
      no: '2',
      name: 'Technical Committee',
      creationdate: '10/12/2020',
    },
    {
      no: '3',
      name: 'Project Manager',
      creationdate: '10/12/2020',
    },
    {
      no: '4',
      name: 'Technical Manager',
      creationdate: '10/12/2020',
    },
    {
      no: '5',
      name: 'Client/Owner',
      creationdate: '10/12/2020',
    },
    {
      no: '6',
      name: 'Project Investigator',
      creationdate: '10/12/2020',
    },
    {
      no: '1',
      name: 'pm',
      creationdate: '10/12/2020',
    },
  ];

  const itemsPerPage = 6;
  const [currentPage, setCurrentPage] = useState(1);
  const [showCreateProjectContainer, setShowCreateProjectContainer] = useState(false);
  const [selectedRole, setSelectedRole] = useState(null);
  const [actionType, setActionType] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');

  const handleCreateProject = (action) => {
    setActionType(action);
    setShowCreateProjectContainer(true);
  };

  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handlePreviousPage = () => {
    setCurrentPage((prevPage) => Math.max(prevPage - 1, 1));
  };

  const handleNextPage = () => {
    setCurrentPage((prevPage) => Math.min(prevPage + 1, totalPages));
  };

  const handleCloseModal = () => {
    setShowCreateProjectContainer(false);
    setSelectedRole(null);
    setActionType(null);
  };

  const handleView = (role) => {
    setSelectedRole(role);
    handleCreateProject('View');
  };

  const handleEdit = (role) => {
    setSelectedRole(role);
    handleCreateProject('Edit');
  };

  const handleDelete = (role) => {
    setSelectedRole(role);
    handleCreateProject('Delete');
  };

  const handleCreate = () => {
    handleCreateProject('Create');
  };

  const totalPages = Math.ceil(rolesData.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = Math.min(startIndex + itemsPerPage, rolesData.length);
  const displayedRoles = rolesData
    .filter((role) => role.name.toLowerCase().includes(searchTerm.toLowerCase()))
    .slice(startIndex, endIndex);

  useEffect(() => {
    const handleClickOutsideModal = (event) => {
      const modal = document.querySelector('.add-role-container');
      if (modal && !modal.contains(event.target)) {
        handleCloseModal();
      }
    };
    document.addEventListener('mousedown', handleClickOutsideModal);
    return () => {
      document.removeEventListener('mousedown', handleClickOutsideModal);
    };
  }, []);

  return (
    <div className='projects-wrapper'>
    <div className="roles-container">
      <div className="proj-title">Roles</div>
      <div className='search-add-role'>
        <div className="role-search">
          <img src={SearchIcon} alt="Search Icon" />
          <input
            type="text"
            placeholder="Search by Role Name"
            className="role-search-input"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button className="add-role-button" onClick={handleCreate}>
          + Add New Role
        </button>
      </div>
      <div className="role">
        <table>
          <thead>
            <tr>
              <th className='numb'>No</th>
              <th>Role Name</th>
              <th>Creation Date</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {displayedRoles.map((role, index) => (
              <tr key={index}>
                <td className='numb'>{role.no}</td>
                <td className='td-role-name'>{role.name}</td>
                <td className='creation-date'>
                  {role.creationdate}
                </td>
                <td>
                  <div className='actions'>
                    <button className="role-view-button" onClick={() => handleView(role)}>View</button>
                    <button className="role-edit-button" onClick={() => handleEdit(role)}>Edit</button>
                    <button className="role-delete-button" onClick={() => handleDelete(role)}>Delete</button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="pagination">
        <button className="prev-button" onClick={handlePreviousPage}> Previous</button>
        {Array.from({ length: totalPages }, (_, index) => (
          <span
            key={index + 1}
            className={currentPage === index + 1 ? 'active-page' : ''}
            onClick={() => handlePageChange(index + 1)}
          >
            {index + 1}
          </span>
        ))}
        <button className='next-button' onClick={handleNextPage}>Next</button>
      </div>

      {showCreateProjectContainer && (
        <div className="role-modal-overlay">
          <div className='add-role-container'>
            <div className="modal">
              <button className="close-modal" onClick={handleCloseModal}>
                X
              </button>
              {actionType === 'View' && (
                <div>
                  {<RoleView />}
                </div>
              )}
              {actionType === 'Edit' && (
                <div>
                 {<RoleEdit />}
                  
                </div>
              )}
              {actionType === 'Delete' && (
                <div>
                  <h2>Delete Modal Content</h2>
                  <p>{selectedRole && selectedRole.name}</p>
                </div>
              )}
              {actionType === 'Create' && (
                <div>
                  <RoleAdd />
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
    </div>
  );
};

export default Roles;
