import React, { useEffect, useState } from "react";
import Swal from "sweetalert2";
import apiService from "../services/apiServices";
import "./Rolesmodal.css";

const RoleEdit = ({ handleCloseModal, handlefetchRoles, roleId }) => {
  const [selectedPermissions, setSelectedPermissions] = useState([]);
  const [roleName, setRoleName] = useState("");
  const [rolePermission, setRolePermission] = useState([]);
  const [selectAll, setSelectAll] = useState(false);
  const [selectedPermission, setSelectedPermission] = useState([]);

  const handleSelectAll = () => {
    if (selectAll) {
      setSelectedPermissions([]);
    } else {
      setSelectedPermissions(rolePermission);
    }
    setSelectAll(!selectAll);
  };

  useEffect(() => {
    const fetchRole = async () => {
      try {
        const role = await apiService.getRoleById(roleId);
        setRoleName(role.name);
        setSelectedPermissions(role.Permissions);
        console.log("selected permissions...", role.Permissions);
      } catch (error) {
        console.error("Error fetching role:", error);
      }
    };

    const fetchPermission = async () => {
      try {
        const permission = await apiService.getPermission();
        setRolePermission(permission);
      } catch (error) {
        console.error("Error fetching permissions:", error);
      }
    };

    fetchRole();
    fetchPermission();
  }, [roleId]);

  const handlePermissionChange = (permission) => {
    if (
      selectedPermissions.some(
        (selected) => selected.permission_id == permission.permission_id
      )
    ) {
      setSelectedPermissions(
        selectedPermissions.filter(
          (selected) => selected.permission_id !== permission.permission_id
        )
      );
      console.log();
    } else {
      setSelectedPermissions([...selectedPermissions, permission]);
    }
  };

  const groupedPermissions = rolePermission.reduce((acc, permission) => {
    const groupCode = permission.group_code;
    if (!acc[groupCode]) {
      acc[groupCode] = [];
    }
    acc[groupCode].push(permission);
    return acc;
  }, {});
  const handleRoleNameChange = (event) => {
    setRoleName(event.target.value);
  };
  const permissionsByGroup = {};
  rolePermission.forEach((permission) => {
    if (!permissionsByGroup[permission.groupCode]) {
      permissionsByGroup[permission.groupCode] = [];
    }
    permissionsByGroup[permission.groupCode].push(permission);
  });

  const handleSaveChanges = async () => {
    try {
      await apiService.updateRole({
        id: roleId,
        name: roleName,
        permissions: selectedPermissions,
      });
      const Toast = Swal.mixin({
        toast: true,
        position: "top-end",
        showConfirmButton: false,
        timer: 1500,
        timerProgressBar: true,
        didOpen: (toast) => {
          toast.onmouseenter = Swal.stopTimer;
          toast.onmouseleave = Swal.resumeTimer;
        },
      });

      Toast.fire({
        icon: "success",
        title: "Role updated successfully",
      }).then(() => {
        handleCloseModal();
        handlefetchRoles();
      });
    } catch (error) {
      console.error("Error saving changes:", error);
      Swal.fire({
        position: "center",
        icon: "error",
        title: "Failed to update Role",
        showConfirmButton: false,
        timer: 2500,
      });
    }
  };

  // const permissionsRows = rolePermission.map((permission, index) => (
  //   <div key={index}>
  //     <div className="sub-title">{permission.permissionCategory}</div>
  //     <div className="permissions-row">

  //     </div>
  //   </div>
  // ));

  const permissionsRows = Object.entries(groupedPermissions)
    .reduce((rows, [groupCode, permissions], index) => {
      if (index % 4 === 0) {
        rows.push([]);
      }
      rows[rows.length - 1].push(
        <div key={groupCode} className="w-1/4">
          <div className="text-blue-900 text-xl mb-2 mx-5">
            <strong>
              {groupCode === "1" && "Organization"}
              {groupCode === "2" && "Member"}
              {groupCode === "3" && "Project"}
              {groupCode === "4" && "Activity"}
              {groupCode === "5" && "Task"}
              {groupCode === "6" && "Subtask"}
              {groupCode === "7" && "Team"}
              {groupCode === "8" && "Dashboard"}
              {groupCode === "9" && "Trash"}
              {groupCode === "10" && "Milestone"}


            </strong>
          </div>
          <div className="">
            {permissions.map((permission) => (
              <label className="checkbox-label">
                <input
                  type="checkbox"
                  className="mr-2"
                  checked={selectedPermissions.some(
                    (selected) =>
                      selected.permission_id == permission.permission_id
                  )}
                  onChange={() => handlePermissionChange(permission)}
                />
                {permission.name}
              </label>
            ))}
          </div>
        </div>
      );
      return rows;
    }, [])
    .map((row, index) => (
      <div key={index} className="flex">
        {row}
      </div>
    ));

  const emptyPlaceholders = Array(
    Math.ceil(Object.keys(groupedPermissions).length / 4) * 4 -
      Object.keys(groupedPermissions).length
  )
    .fill(null)
    .map((_, index) => <div key={index} className="w-1/4" />);

  return (
    <div className="mx-5 h-96 mb-5 overflow-y-auto">
      <div className="">
        <div className="role-title mx-5">Edit Role</div>
        <div className="mx-5">Role Name </div>
        <div className="">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={selectAll}
              onChange={handleSelectAll}
              className="mr-2 my-2"
            />
            Select All
          </label>
        </div>
        <div className="mx-5">
          <input
            type="text"
            className="px-3"
            value={roleName}
            onChange={handleRoleNameChange}
            required
          />
        </div>
        <div
          className="text-xl font-bold font-poppins ml-5  mb-5 "
          style={{ color: "#172B4D" }}
        >
          Permissions
        </div>
        <div>{permissionsRows}</div>
        <div className="flex">{emptyPlaceholders}</div>
        <div className="justify-end flex  gap-7 my-6">
          <button type="button" onClick={handleCloseModal}>
            Cancel
          </button>
          <button
            className="text-white font-bold py-2 px-4 rounded"
            style={{ backgroundColor: "#082f49" }}
            onClick={handleSaveChanges}
          >
            Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default RoleEdit;
