import VisibilityOffOutlinedIcon from "@mui/icons-material/VisibilityOffOutlined";
import VisibilityOutlinedIcon from "@mui/icons-material/VisibilityOutlined";
import React, { useEffect, useRef, useState } from "react";
import Leader from "../Assets/Leader.png";
import apiService from "../services/apiServices";
import Registernewuser from "./Registernewuser";
import UserStatus from "./UserStatus.jsx";
import "./Users.css";

const Users = () => {
  // const usersData = [
  //   {
  //     name: "User 1",
  //     email: "user1@example.com",
  //     status: "Inactive",
  //     project: "Assigned",
  //     profilePicture: "member1.png",
  //   },
  //   {
  //     name: "User 2",
  //     email: "user2@example.com",
  //     status: "Active",
  //     project: "Assigned",
  //     profilePicture: "member1.png",
  //   },
  //   {
  //     name: "User 3",
  //     email: "user3@example.com",
  //     status: "Active",
  //     project: "Unassigned",
  //     profilePicture: "leader.png",
  //   },
  //   {
  //     name: "User 4",
  //     email: "user4@example.com",
  //     status: "Inactive",
  //     project: "Assigned",
  //     profilePicture: "leader.png",
  //   },
  //   {
  //     name: "User 5",
  //     email: "user5@example.com",
  //     status: "Active",
  //     project: "Unassigned",
  //     profilePicture: "leader.png",
  //   },
  //   {
  //     name: "User 6",
  //     email: "user6@example.com",
  //     status: "Inactive",
  //     project: "Unassigned",
  //     profilePicture: "leader.png",
  //   },
  //   {
  //     name: "User 2",
  //     email: "user6@example.com",
  //     status: "Inactive",
  //     project: "Unassigned",
  //     profilePicture: "leader.png",
  //   },
  // ];

  const itemsPerPage = 6;
  const [showConfirmModal, setShowConfirmModal] = useState(false); // State variable to control the visibility of the confirmation modal
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedStatus, setSelectedStatus] = useState("All");
  const [usersData, setUsersData] = useState([]);
  const totalPages = Math.ceil(usersData.length / itemsPerPage);
  const [showCreateUserModal, setShowCreateUserModal] = useState(false);
  const [isSecureEntry, setIsSecureEntry] = useState(true);
  const [eyeIcon, setEyeIcon] = useState("eye");
  const [selectedUser, setSelectedUser] = useState();
  const [selectedUserForStatusChange, setSelectedUserForStatusChange] =
    useState(null);
  const [userStatus, setUserStatus] = useState();
  const [changeStatus, setChangeStatus] = useState(true);
  const [selectedUser2, setSelectedUser2] = useState();
  const [userInfo, setUserInfo] = useState(() => {
    return JSON.parse(localStorage.getItem("userInfo")) || [];
  });

  const handleStatusFilter = (status) => {
    setCurrentPage(1);
    setSelectedStatus(status);
  };
  const handlePasswordVisibility = (id) => {
    setSelectedUser(id);
    if (eyeIcon === "eye") {
      setEyeIcon("eye-off");
      setIsSecureEntry(!isSecureEntry);
    } else if (eyeIcon === "eye-off") {
      setEyeIcon("eye");
      setIsSecureEntry(!isSecureEntry);
    }
  };
  const handleClickOutsideModal = (e) => {
    if (modalRef.current && !modalRef.current.contains(e.target)) {
      setShowConfirmModal(false);
    }
  };
  const handleStatusChange = (id) => {
    setSelectedUserForStatusChange(id);
    setShowConfirmModal(true);
  };
  const test = "Active";
  const handleCreateUser = () => {
    setShowCreateUserModal(true);
  };
  const handleCloseModal = () => {
    setShowCreateUserModal(false);
  };
  const handlePageChange = (page) => {
    setCurrentPage(page);
  };

  const handlePreviousPage = () => {
    setCurrentPage((prevPage) => Math.max(prevPage - 1, 1));
  };

  const handleNextPage = () => {
    setCurrentPage((prevPage) => Math.min(prevPage + 1, totalPages));
  };
  const confirmStatusChange = async () => {
    await apiService.updateUserStatus(selectedUserForStatusChange);
    setShowConfirmModal(false);
    await fetchData();
  };
  const cancelStatusChange = () => {
    setSelectedUserForStatusChange(null);
    setShowConfirmModal(false);
  };

  const modalRef = useRef(null);
  const toggleConfirmModal = () => setShowConfirmModal(!showConfirmModal);

  const filteredUsers =
    selectedStatus === "All"
      ? usersData
      : usersData.filter(
          (user) =>
            JSON.stringify(test).toLowerCase() === selectedStatus.toLowerCase()
        );

  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const displayedUsers = filteredUsers?.slice(startIndex, endIndex);
  const fetchData = async () => {
    console.log("Sdsds", userInfo.access_token);
    try {
      const response = await apiService.getAllUsers(
        "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..JE0kj8XFg9Eh8-jaup_UVD6f-mIVlcBT9gZ0lxtthtk"
      );

      const sortedResponse = response.sort((a, b) => {
        if (a.createdAt > b.createdAt) {
          return -1;
        }
      });
      setUsersData(sortedResponse);
    } catch (error) {
      console.error("Error fetching user data:", error);
    }
  };
  useEffect(() => {
    fetchData();
    const handleClickOutsideModal = (event) => {
      const modal = document.querySelector(".create-user-container");
      if (modal && !modal.contains(event.target)) {
        handleCloseModal();
      }
    };

    document.addEventListener("mousedown", handleClickOutsideModal);

    return () => {
      document.removeEventListener("mousedown", handleClickOutsideModal);
    };
  }, [userStatus]);
  useEffect(() => {
    document.addEventListener("mousedown", handleClickOutsideModal);
    return () => {
      document.removeEventListener("mousedown", handleClickOutsideModal);
    };
    async function fetchUsers() {
      localStorage.setItem("userInfo", JSON.stringify(userInfo));
    }
    fetchUsers();
  }, [userInfo]);

  return (
    <div className="projects-wrapper">
      <div className="projects-container">
        <div className="proj-title">Members</div>
        <div className="status-filter">
          <span
            className={selectedStatus === "All" ? "active-filter" : ""}
            onClick={() => handleStatusFilter("All")}
          >
            All
          </span>
          <span
            className={selectedStatus === "Active" ? "active-filter" : ""}
            onClick={() => handleStatusFilter("Active")}
          >
            Active
          </span>
          <span
            className={selectedStatus === "Inactive" ? "active-filter" : ""}
            onClick={() => handleStatusFilter("Inactive")}
          >
            Inactive
          </span>
          <button className="create-user-button" onClick={handleCreateUser}>
            + Register Member
          </button>
        </div>

        <div className="users">
          <table>
            <thead>
              <tr>
                <th>Full Name</th>
                <th>Email</th>
                <th>Password</th>
                <th className="status">Gender</th>
                <th>Status</th>
                <th>Project</th>
              </tr>
            </thead>
            <tbody>
              {displayedUsers.map((user, index) => (
                <tr key={index}>
                  <td>
                    <div className="flex flex-row">
                      <img
                        src={Leader}
                        alt="Profile"
                        className="profile-image"
                      />
                      <div>{user.full_name}</div>
                    </div>
                  </td>
                  <td
                    className={`email-cell ${JSON.stringify(
                      user.account_status
                    ).toLowerCase()}`}
                  >
                    {user.email}
                  </td>
                  <td>
                    <div className="flex flex-row items-center gap-3">
                      <div className="text-center cursor-pointer">
                        <div
                          onClick={() => handlePasswordVisibility(user.user_id)}
                        >
                          {eyeIcon === "eye" &&
                          user.user_id === selectedUser ? (
                            <VisibilityOffOutlinedIcon />
                          ) : (
                            <VisibilityOutlinedIcon />
                          )}
                        </div>
                      </div>
                      {isSecureEntry && user.user_id === selectedUser ? (
                        <div>{user.unchanged_password}</div>
                      ) : (
                        <div>*****</div>
                      )}
                    </div>
                  </td>
                  <td>
                    <div className="flex flex-row">
                      <div>{user.gender}</div>
                    </div>
                  </td>
                  <td
                    className={JSON.stringify(
                      user.account_status
                    ).toLowerCase()}
                  >
                    <div
                      style={{ alignItems: "center" }}
                      className="cursor-pointer"
                      onClick={() => handleStatusChange(user.user_id)}
                    >
                      {user.account_status === true ? (
                        <span className="active">Active</span>
                      ) : (
                        <span className="inactive">Inactive</span>
                      )}
                    </div>
                  </td>
                  <td
                    className={JSON.stringify(
                      user.project_status
                    ).toLowerCase()}
                  >
                    <div style={{ alignItems: "center" }}>
                      {JSON.stringify(user.project_status) === "true" && (
                        <span className="active">Assigned</span>
                      )}
                      {JSON.stringify(user.project_status) === "false" && (
                        <span className="inactive">Unassigned</span>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        <div className="pagination">
          <button className="prev-button" onClick={handlePreviousPage}>
            {" "}
            Previous
          </button>
          {Array.from({ length: totalPages }, (_, index) => (
            <span
              key={index + 1}
              className={currentPage === index + 1 ? "active-page" : ""}
              onClick={() => handlePageChange(index + 1)}
            >
              {index + 1}
            </span>
          ))}
          <button className="next-button" onClick={handleNextPage}>
            Next
          </button>
        </div>
        {showCreateUserModal && (
          <div className="modal-overlay">
            <div className="create-user-container">
              <div className="modals">
                <button className="close-modals" onClick={handleCloseModal}>
                  X
                </button>
                <Registernewuser />
              </div>
            </div>
          </div>
        )}
        {showConfirmModal && (
          <div className="modal-overlay">
            <div className="confirm-modal-container">
              <div className="fixed top-0 left-0 w-full h-full z-70 flex items-center justify-center bg-gray-800 bg-opacity-50">
                <div className="bg-white w-2/3 p-8 h-fit rounded-md relative">
                  <span
                    onClick={toggleConfirmModal}
                    className="absolute top-4 right-8 cursor-pointer text-gray-500"
                  >
                    X
                  </span>
                  <UserStatus />
                  <div className="mt-4 flex justify-end">
                    <button
                      className="bg-white text-black py-2 px-4 rounded mr-4"
                      onClick={cancelStatusChange}
                    >
                      Cancel
                    </button>
                    <button
                      className="bg-blue-500 text-white py-2 px-4 rounded"
                      onClick={confirmStatusChange}
                    >
                      Confirm
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Users;
