import React, { useState } from "react";

const Activitiesdetail = ({
  selectedRow,
  handleCloseModal,
  selectedRowAllData,
}) => {
  const [memberOptions, setMemberOptions] = useState([]);
  const [members, setMembers] = useState([]);

  return (
    <div>
      <div className="flex flex-col pr-9 pl-10 bg-white rounded-2xl max-w-[925px] max-md:px-5">
        <div className="self-start text-2xl font-bold text-blue-950">
          Activity Details
        </div>
        <div className="justify-end mt-7 max-md:max-w-full">
          <div className="flex gap-5 max-md:flex-col max-md:gap-0">
            <div className="flex flex-col w-6/12 max-md:ml-0 max-md:w-full">
              <div className="flex flex-col py-1 text-base text-slate-950 max-md:mt-10">
                <div className=""><strong>Activity Name</strong></div>
                <div className="h-12 p-2">{selectedRow.name}</div>

                <div className="mt-2"><strong>Activity Status</strong></div>

                <div className="h-12 p-2">{selectedRow.activity_status}</div>

                <div className="mt-2"><strong>Members</strong></div>
                <div className="h-12 p-2">
                  <ul>
                    {selectedRow.members.map((member) => (
                      <li>{member.UserInfo.full_name}</li>
                    ))}
                  </ul>
                </div>
              </div>
            </div>
            <div className="flex flex-col ml-5 w-6/12 max-md:ml-0 max-md:w-full">
              <div className="flex flex-col grow py-1 text-base max-md:mt-10">
                <div className=""><strong>Activity Start Date</strong></div>

                <div className="h-12 p-2">
                  {new Date(selectedRow.start_date).toLocaleDateString()}
                </div>

                <div className="mt-8"> <strong>Activity End Date</strong></div>
                <div className="h-12 p-2">
                  {new Date(selectedRow.end_date).toLocaleDateString()}
                </div>
                <div className="mt-2"><strong>Tasks</strong></div>
                <div className="h-12 p-2">
                  {selectedRowAllData.tasks.length !== 0 ? (
                    <ul>
                      {selectedRowAllData.tasks.map((task) => (
                        <li>{task.name}</li>
                      ))}
                    </ul>
                  ) : (
                    <div>No Task Found</div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Activitiesdetail;
