import React, { useEffect, useState } from "react";
import Select from "react-select";
import Swal from "sweetalert2";
import apiService from "../services/apiServices";
import "./Registernewuser.css";

const Registernewuser = ({ handleCloseModal, handlefetchUsers }) => {
  const [emailError, setEmailError] = useState("");
  const [divisions, setDivisions] = useState([]);
  const [sectors, setSectors] = useState([]);

  const [roles, setRoles] = useState([]);
  const [userInfo, setUserInfo] = useState(() => {
    return JSON.parse(localStorage.getItem("userInfo")) || [];
  });
  const [formData, setFormData] = useState({
    full_name: "",
    email: "",
    division: "",
    sector: "",
    role: "",
    password: "",
    isRoot: false,
    isSector: false,
    isOrganizationUnit: false,
  });

  useEffect(() => {
    fetchDivisions();
    fetchSectors();

    fetchRoles();
    async function fetchUsers() {
      localStorage.setItem("userInfo", JSON.stringify(userInfo));
    }
    fetchUsers();
  }, [userInfo]);

  const fetchDivisions = async () => {
    try {
      const divisionsData = await apiService.getDivisions(
        userInfo.access_token
      );
      setDivisions(divisionsData);
    } catch (error) {
      console.error("Error fetching divisions:", error.message);
    }
  };
  const fetchSectors = async () => {
    try {
      const sectorsData = await apiService.getallOrganizations(
        userInfo.access_token
      );
      console.log(sectorsData);
      setSectors(sectorsData);
    } catch (error) {
      console.error("Error fetching sectors:", error.message);
    }
  };

  const fetchRoles = async () => {
    try {
      const rolesData = await apiService.getRoles(userInfo.access_token);

      const nonProjectRole = rolesData.filter(
        (role) => role.project_related === false
      );
      setRoles(nonProjectRole);
    } catch (error) {
      console.error("Error fetching roles:", error.message);
    }
  };

  const handleChange = (selectedOption, name) => {
    setFormData({
      ...formData,
      [name]: selectedOption.value,
    });
  };

  const handleCheckboxChange = (e) => {
    const { name, checked } = e.target;
    const updatedFormData = {
      ...formData,
      [name]: checked,
    };

    if (name === "isSector" && checked) {
      updatedFormData.isRoot = false;
      updatedFormData.isOrganizationUnit = false;
    } else if (name === "isRoot" && checked) {
      updatedFormData.isSector = false;
      updatedFormData.isOrganizationUnit = false;
    } else if (name === "isOrganizationUnit" && checked) {
      updatedFormData.isRoot = false;
      updatedFormData.isSector = false;
    }

    setFormData(updatedFormData);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (emailError) {
      console.error("Invalid email address");
      return;
    }

    try {
      const response = await apiService.registerUser(formData);
      console.log("User registration response:", response);

      if (response.success) {
        setFormData({
          full_name: "",
          email: "",
          division: "",
          role: "",
          gender: "",
          isRoot: false,
          isSector: false,
          isOrganizationUnit: false,
        });

        const Toast = Swal.mixin({
          toast: true,
          position: "top-end",
          showConfirmButton: false,
          timer: 1000,
          timerProgressBar: true,
          didOpen: (toast) => {
            toast.onmouseenter = Swal.stopTimer;
            toast.onmouseleave = Swal.resumeTimer;
          },
        });

        Toast.fire({
          icon: "success",
          title: "User Registered successfully",
        }).then(() => {
          handleCloseModal();
          handlefetchUsers();
        });
      } else {
        console.error("User registration failed");
      }
    } catch (error) {
      console.error("Registration failed:", error.message);
      Swal.fire({
        position: "center",
        icon: "error",
        title: "Failed to register a member",
        text: error.response.data.message,
        showConfirmButton: false,
        timer: 2500,
      });
    }
  };

  const handleCancel = () => {};

  return (
    <div className="px-4">
      <h2 className="role-title">Register New Member</h2>
      <form>
        <div className="flex flex-wrap">
          <div className="form-group">
            <label htmlFor="full_name" className="required">
              Full Name
            </label>
            <input
              type="text"
              id="full_name"
              className="w-80 pl-3 h-14 mb-4"
              name="full_name"
              value={formData.full_name}
              onChange={(e) =>
                setFormData({ ...formData, full_name: e.target.value })
              }
              placeholder="Enter Full Name"
            />
            <div className="form-row">
              <div className="form-group">
                <label htmlFor="email" className="required">
                  Email
                </label>
                <input
                  type="email"
                  id="email"
                  name="email"
                  className="w-80 pl-3 h-14"
                  value={formData.email}
                  onChange={(e) =>
                    setFormData({ ...formData, email: e.target.value })
                  }
                  placeholder="example@example.com"
                />
                {emailError && (
                  <div className="error-message">{emailError}</div>
                )}
              </div>
            </div>
            {!formData.isRoot && !formData.isSector && (
              <div className="form-group">
                <label htmlFor="divisions" className="required">
                  Department
                </label>
                <Select
                  id="divisions"
                  className="w-80"
                  name="division"
                  value={{
                    value: formData.division,
                    label:
                      divisions.find(
                        (division) =>
                          division.division.division_id === formData.division
                      )?.division.name || "",
                  }}
                  onChange={(selectedOption) =>
                    handleChange(selectedOption, "division")
                  }
                  options={divisions.map((division) => ({
                    value: division.division.division_id,
                    label: division.division.name,
                  }))}
                  placeholder="Select Division"
                />
              </div>
            )}
            {formData.isSector && !formData.isRoot && (
              <div className="form-group">
                <label htmlFor="Sectors" className="required">
                  Sectors
                </label>
                <Select
                  id="sectors"
                  className="w-80"
                  name="sector"
                  value={{
                    value: formData.sector,
                    label:
                      sectors.find(
                        (sector) => sector.sector.sector_id === formData.sector
                      )?.name || "",
                  }}
                  onChange={(selectedOption) =>
                    handleChange(selectedOption, "sector")
                  }
                  options={sectors.map((sector) => ({
                    value: sector.sector.sector_id,
                    label: sector.sector.name,
                  }))}
                  placeholder="Select Sector"
                />
              </div>
            )}
          </div>

          <div className="form-group ml-5 ">
            <label htmlFor="roles" className="required">
              Role
            </label>
            <Select
              id="role"
              className="w-80 mb-4"
              name="role"
              value={{
                value: formData.role,
                label:
                  roles.find((role) => role.role_id === formData.role)?.name ||
                  "",
              }}
              onChange={(selectedOption) =>
                handleChange(selectedOption, "role")
              }
              options={roles.map((role) => ({
                value: role.role_id,
                label: role.name,
              }))}
              placeholder="Select Division"
            />
            <div className="form-group">
              <label htmlFor="gender" className="required">
                Gender
              </label>
              <Select
                id="gender"
                name="gender"
                value={{ value: formData.gender, label: formData.gender }}
                onChange={(selectedOption) =>
                  handleChange(selectedOption, "gender")
                }
                options={[
                  { value: "male", label: "Male" },
                  { value: "female", label: "Female" },
                ]}
                placeholder="Select Gender"
              />
            </div>
            <div className="-ml-32 mt-36">
              {/* <div className=" flex items-center">
                <input
                  type="checkbox"
                  id="isRoot"
                  name="isRoot"
                  style={{ transform: "scale(0.5)" }}
                  checked={formData.isRoot}
                  onChange={handleCheckboxChange}
                />
                <label htmlFor="isRoot" className="-ml-32">
                  Is Root?
                </label>
              </div> */}

              {/* <div className="checkbox-group flex items-center">
                <input
                  type="checkbox"
                  id="isSector"
                  name="isSector"
                  className="transform scale-50"
                  checked={formData.isSector}
                  onChange={handleCheckboxChange}
                />
                <label htmlFor="isSector" className="-ml-32">
                  Is Sector?
                </label>
              </div> */}

              {/* <div className=" flex">
                <input
                  type="checkbox"
                  id="isOrganizationUnit"
                  name="isOrganizationUnit"
                  className="scale-50"
                  checked={formData.isOrganizationUnit}
                  onChange={handleCheckboxChange}
                />
                <label htmlFor="isOrganizationUnit" className="-ml-32">Is Organization Unit?</label>

              </div> */}
              <div className="flex justify-end">
                <button onClick={handleCloseModal} className="bg-white mr-4">
                  Cancel
                </button>
                <button
                  className="text-white font-bold py-2 px-4 rounded"
                  onClick={handleSubmit}
                  style={{ backgroundColor: "#082f49" }}
                >
                  Register
                </button>
              </div>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

export default Registernewuser;
