import React, { useState } from 'react';

const DocsEdit = ({ closeModal }) => {

  const [project, setProject] = useState('Received project');
  const [doctype, setDoctype] = useState('Abebe Kebede');
  const [description, setDescription] = useState('This is a document of the project named Smart Court System. Please check it out.');
  const [file, setFile] = useState('roro.png');
  const [showModal, setShowModal] = useState(false);
  const [newDocType, setNewDocType] = useState('');

  const handleProjectChange = (event) => {
    setProject(event.target.value);
  };

  const handleDoctypeChange = (event) => {
    setDoctype(event.target.value);
  };

  const handleDescriptionChange = (event) => {
    setDescription(event.target.value);
  };

  const handleFileChange = (event) => {
    setFile(event.target.value);
  };

  const handleSaveChanges = () => {
    console.log('Adding...');
  };

  const handleCancel = () => {
    closeModal();
  };

  const handleAddDocType = () => {
    setShowModal(true);
  };

  const handleModalClose = () => {
    setShowModal(false);
    setNewDocType('');
  };


  const handleNewDocTypeChange = (event) => {
    setNewDocType(event.target.value);
  };

  const handleConfirmAddDocType = () => {
    setDoctype(newDocType);
    handleModalClose();
  };

  return (
    <div>
      <div className="flex flex-row py-12 pr-9 pl-20 bg-white rounded-2xl max-w-[925px] max-md:px-5">
        <div className="flex flex-col w-6/12">
          <div className="text-2xl font-bold text-blue-950 max-md:max-w-full">
           Add Documents
          </div>
          <div className="mt-8 max-md:max-w-full">
            <div className="flex flex-col grow py-1 text-base text-slate-950 max-md:mt-10">
              <div>Project</div>
              <input
                type="text"
                placeholder={project ? project : 'Received project'}
                value={project}
                onChange={handleProjectChange}
                className={`justify-center items-start px-4 py-5 mt-3.5 text-sm rounded-lg bg-zinc-100 max-md:pr-5 text-gray-400 ${project ? 'text-black' : ''}`}
              />
              <div className=' flex flex-row'>
              <div className="mt-8 ">Document Type</div>
              <div className=" cursor-pointer ml-48 mt-8 bg-gray-200 px-2 pb-1 font-bold text-lg rounded-full  text-black " onClick={handleAddDocType}>+</div>
              </div>
              <div className="flex">
                <select
                  onChange={handleDoctypeChange}
                  className={`px-4 mt-3.5 text-sm rounded-lg bg-zinc-100 max-md:pr-5 border-gray-300 focus:outline-none text-gray-400 ${doctype ? 'text-black' : ''}`}
                  required
                >
                  <option value={doctype}>{doctype}</option>
                  <option value="doctype1">doctype 1</option>
                  <option value="doctype2">doctype 2</option>
                  <option value="doctype3">doctype 3</option>

                </select>
              </div>
              <div className="mt-8">Project Related Documents</div>
              <input
                type="file"
                placeholder={file}
                onChange={handleFileChange}
                className="px-4 mt-3.5 text-sm rounded-lg bg-zinc-100 max-md:pr-5 border-gray-300"
              />
            </div>
          </div>
        </div>
        <div className="mt-16 flex flex-col ml-5 w-6/12 max-md:ml-0 max-md:w-96">
          <div className="flex flex-col grow py-1 text-base text-slate-950 max-md:mt-10">
            <div className="text-slate-950">Description</div>
            <textarea
              placeholder= 'Enter description...'
              value={description}
              onChange={handleDescriptionChange}
              className={`px-4 pt-5 pb-20 mt-3 text-sm rounded-lg bg-zinc-100 text-gray-400 ${description ? 'text-black' : ''}`}
            ></textarea>
          </div>
        </div>
      </div>
      <div className="flex gap-5 -mt-24 mb-6 mr-12 justify-end text-base">
        <button
          className="my-auto bg-white text-black border-black px-4 py-2 rounded-lg"
          onClick={handleCancel}
        >
          Cancel
        </button>
        <button
          className="justify-center p-2.5 font-bold text-white bg-sky-500 rounded-lg"
          onClick={handleSaveChanges}
        >
          Add Document
        </button>
      </div>
      {showModal && (
        <div className="fixed top-0 left-0 w-full h-full bg-gray-500 bg-opacity-50 flex justify-center items-center">
          <div className="bg-white p-6 rounded-lg">
            <div className="text-xl font-bold mb-4">Add New Document Type</div>
            <input
              type="text"
              placeholder="Enter new document type"
              value={newDocType}
              onChange={handleNewDocTypeChange}
              className=" border-gray-300 rounded px-4 py-2 mb-4"
            />
            <div className="flex justify-end">
              <button className="bg-gray-300 text-gray-800 px-4 py-2 rounded mr-2" onClick={handleModalClose}>Cancel</button>
              <button className="bg-blue-500 text-white px-4 py-2 rounded" onClick={handleConfirmAddDocType}>Add Document</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DocsEdit;
