import React, { useEffect, useState } from "react";
import DatePicker from "react-datepicker";
import Select from "react-select";
import Swal from "sweetalert2";
import apiService from "../services/apiServices";

import "react-datepicker/dist/react-datepicker.css";

const Activityadd = ({
  selectedProject,
  handleCloseModal,
  handlefetchActivity,
}) => {
  const [formData, setFormData] = useState({
    name: "",
    activity_status: "Pending",
    start_date: "",
    end_date: "",
    projectmembers: [],
    is_milestone: false,

  });
  const [members, setMembers] = useState([]);
  const [memberOptions, setMemberOptions] = useState([]);
  const [selectedStartDate, setSelectedStartDate] = useState(
    new Date(selectedProject.start_date)
  );
  const [selectedEndDate, setSelectedEndDate] = useState(
    new Date(selectedProject.end_date)
  );
  const [startDate, setStartDate] = useState(
    new Date(selectedProject.start_date)
  );
  const [endDate, setEndDate] = useState(new Date(selectedProject.end_date));

  const customStyles = {
    control: (provided, state) => ({
      ...provided,
      backgroundColor: "#f3f4f6",
    }),
    dropdownIndicator: (provided, state) => ({
      ...provided,
      marginTop: "-5px",
    }),
    indicatorSeparator: (provided, state) => ({
      ...provided,
      display: "none",
    }),
  };

  const handleMemberChange = (selectedOption) => {
    const selectedValues = selectedOption.map((option) => option.value);
    setMembers(selectedValues);
  };
  const handleInputChange = (event) => {
    const { name, value, checked } = event.target; 
    setFormData({
      ...formData,
      [name]: name === 'is_milestone' ? checked : value, 
    });
  }

  const handleAddActivity = async (e) => {
    e.preventDefault();
    formData.start_date = selectedStartDate;
    formData.end_date = selectedEndDate;
    formData.projectmembers.push(...members);
    try {
      const response = await apiService.activityadd(
        formData,
        selectedProject.project_id
      );
      console.log("Activity creation response:", response);

      // Check if the registration was successful based on the response
      if (response.message === "New activity created") {
        // Assuming the response contains a "success" property
        // Clear the form data
        setFormData({
          name: "",
          startDate: "",
          endDate: "",
          projectmembers: [],
        });
        const Toast = Swal.mixin({
          toast: true,
          position: "top-end",
          showConfirmButton: false,
          timer: 1500,
          timerProgressBar: true,
          didOpen: (toast) => {
            toast.onmouseenter = Swal.stopTimer;
            toast.onmouseleave = Swal.resumeTimer;
          },
        });

        Toast.fire({
          icon: "success",
          title: "New Activity has been created",
        }).then(() => {
          handleCloseModal();
          handlefetchActivity();
        });
      } else {
        console.error("User registration failed");
        Swal.fire({
          position: "center",
          icon: "error",
          title: "Activity Registered Failed",
          showConfirmButton: true,
          timer: 1500,
          customClass: {
            popup: "custom-popup-style",
          },
        });
      }
    } catch (error) {
      console.error("Activity Registration failed:", error);
      Swal.fire({
        position: "center",
        icon: "error",
        title: "Activity Registered Failed",
        text: error.response.data.message,
        showConfirmButton: true,
        timer: 1500,
        customClass: {
          popup: "custom-popup-style",
        },
      });
    }
  };
  useEffect(() => {
    async function fetchUsers() {
      try {
        const users = await apiService.getAllProjectMembers(
          selectedProject.project_id
        );
        console.log(users);
        const options = users.map((user) => ({
          value: user.project_member_id,
          label: user.UserInfo.full_name,
        }));
        setMemberOptions(options);
      } catch (error) {
        console.error("Error fetching users and document types:", error);
      }
    }

    fetchUsers();
  }, []);

  return (
    <div>
      <div className="flex flex-col py-12 pr-9 pl-10 bg-white rounded-2xl max-w-[925px] max-md:px-5">
        <div className="self-start text-2xl font-bold text-blue-950">
          Add Activity
        </div>
        <div className="justify-end mt-7 max-md:max-w-full">
          <div className="flex gap-5 max-md:flex-col max-md:gap-0">
            <div className="flex flex-col w-6/12 max-md:ml-0 max-md:w-full">
              <div className="flex flex-col py-1 text-base text-slate-950 max-md:mt-10">
                <div className="">
                  Name <span className="text-red-600">*</span>
                </div>
                <input
                  type="text"
                  value={formData.name}
                  placeholder="Enter activity name"
                  onChange={(e) =>
                    setFormData({ ...formData, name: e.target.value })
                  }
                  className="h-12 pl-2"
                />

                <div className="mt-8">Member</div>
                <Select
                  name="members"
                  value={members.map((member) => ({
                    value: member,
                    label: memberOptions.find(
                      (option) => option.value === member
                    )?.label,
                  }))}
                  onChange={handleMemberChange}
                  options={memberOptions}
                  isMulti
                  className="mr-10 mt-3"
                  closeMenuOnSelect={false}
                  styles={customStyles}
                />
                 <div className="flex flex-row mt-4  ">  
    <input
        type="checkbox"
        id="is_milestone"
        name="is_milestone"
        checked={formData.is_milestone}
        onChange={handleInputChange}
        className="h-4 w-4 mt-1 text-blue-600 focus:ring-blue-500 border-gray-300 rounded-md"  />
    <label htmlFor="is_milestone" className="ml-3">Is Milestone?</label>
</div>
              </div>
            </div>
            <div className="flex flex-col ml-5 w-6/12 max-md:ml-0 max-md:w-full">
              <div className="flex flex-col grow py-1 text-base max-md:mt-10">
                <div className="">
                  Activity Start Date <span className="text-red-600">*</span>
                </div>

                <DatePicker
                  selected={selectedStartDate}
                  onChange={(selectedStartDate) =>
                    setSelectedStartDate(selectedStartDate)
                  }
                  minDate={startDate}
                  maxDate={endDate}
                  className="h-12 pl-2"
                />
                <div className="mt-8">
                  Activity End Date <span className="text-red-600">*</span>
                </div>

                <DatePicker
                  selected={selectedEndDate}
                  onChange={(selectedEndDate) =>
                    setSelectedEndDate(selectedEndDate)
                  }
                  minDate={selectedStartDate}
                  maxDate={endDate}
                  className="h-12 pl-2"
                />
                <div className="flex gap-5 justify-end self-end mt-6">
                  <div className="my-auto text-black">Cancel</div>
                  <div
                    className="justify-center p-2.5 font-bold text-white bg-blue-900 rounded-lg cursor-pointer"
                    onClick={handleAddActivity}
                  >
                    Add Activity
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Activityadd;
