import React, { useEffect, useState } from "react";
import Select from "react-select";
import Swal from "sweetalert2";
import apiService from "../services/apiServices";
import "./SectorModal.css";

const Organizationaluniteditt = ({
  selectedRow,
  handleCloseModal,
  handlefetchOrganizationalunit,
}) => {
  console.log("Selected Row:", selectedRow);

  const [formData, setFormData] = useState({
    division_name: selectedRow ? selectedRow.division.name : "",
    sectors:
      selectedRow && selectedRow.sector ? selectedRow.sector[0].name : "",
    leader: selectedRow.head.length !== 0 ? selectedRow.head[0].full_name : "",
    leader_id:
      selectedRow && selectedRow.head ? selectedRow.head.leader_id : "",
  });

  console.log(selectedRow);

  const [organizations, setOrganizations] = useState([]);
  const [users, setUsers] = useState([]);
  const [userInfo, setUserInfo] = useState(() => {
    return JSON.parse(localStorage.getItem("userInfo")) || [];
  });
  const fetchOrganizationsAndUsers = async () => {
    try {
      const organizationsData = await apiService.getallOrganizations(
        userInfo.access_token
      );
      const allEmployees = await apiService.getAllUsers(userInfo.access_token);
      setOrganizations(organizationsData);
      setUsers(allEmployees);
    } catch (error) {
      console.error("Error fetching data:", error);
    }
  };

  useEffect(() => {
    fetchOrganizationsAndUsers();
    async function fetchUsers() {
      localStorage.setItem("userInfo", JSON.stringify(userInfo));
    }
    fetchUsers();
  }, [userInfo]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log("Form submitted:", formData);
    try {
      const response = await apiService.updateDepartment(selectedRow, formData);
      console.log(response);

      if (response.message === "Division updated") {
        const Toast = Swal.mixin({
          toast: true,
          position: "top-end",
          showConfirmButton: false,
          timer: 1500,
          timerProgressBar: true,
          didOpen: (toast) => {
            toast.onmouseenter = Swal.stopTimer;
            toast.onmouseleave = Swal.resumeTimer;
          },
        });

        Toast.fire({
          icon: "success",
          title: "Department Updated successfully",
        }).then(() => {
          handleCloseModal();
          handlefetchOrganizationalunit();
        });
      }
    } catch (error) {
      console.error("Error fetching data:", error);
      Swal.fire({
        position: "center",
        icon: "error",
        title: "Failed to update Department",
        text: error.response.data.message,
        showConfirmButton: false,
        timer: 2500,
      });
    }
  };

  const handleCancel = (e) => {
    e.preventDefault();
    setFormData({
      division_name: "",
      sectors: "",
      leader: "",
    });
  };

  const handleChange = (selectedOption, name) => {
    if (name === "sector_id") {
      setFormData({
        ...formData,
        sector_id: selectedOption.value,
        sectors: selectedOption.label,
      });
    } else if (name === "leader") {
      setFormData({
        ...formData,
        leader: selectedOption.label,
        leader_id: selectedOption.value,
      });
    } else {
      setFormData({
        ...formData,
        [name]: selectedOption.value,
      });
    }
  };

  return (
    <div className="create-new-sector-container">
      <div className="role-title">Edit Department</div>
      <form>
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="division_name">Department Name</label>
            <input
              type="text"
              className="w-80 h-14 px-4"
              id="division_name"
              name="division_name"
              value={formData.division_name}
              placeholder="Enter Department Name"
              onChange={(e) =>
                setFormData({ ...formData, division_name: e.target.value })
              }
            />
          </div>
          <div className="form-group">
            <label htmlFor="leader">Leader</label>
            <Select
              name="leader"
              className="w-80"
              value={{ value: formData.leader, label: formData.leader }}
              required
              onChange={(selectedOption) =>
                handleChange(selectedOption, "leader")
              }
              options={users.map((user) => ({
                value: user.user_id,
                label: user ? user.full_name : "",
              }))}
            />
          </div>
        </div>
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="sectors">Sector</label>
            <Select
              name="leader"
              className="w-80"
              value={{ value: formData.sector_id, label: formData.sectors }}
              required
              onChange={(selectedOption) =>
                handleChange(selectedOption, "sector_id")
              }
              options={organizations.map((organization) => ({
                value: organization.sector.sector_id,
                label: organization.sector.name,
              }))}
            />
          </div>
        </div>
        <div className="flex justify-end gap-4 mr-32 -mt-16">
          <button onClick={handleCancel}>Cancel</button>
          <button
            className="px-4 py-2 text-white"
            style={{ backgroundColor: "#082f49" }}
            onClick={handleSubmit}
          >
            Save Changes
          </button>
        </div>
      </form>
    </div>
  );
};

export default Organizationaluniteditt;
