import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import apiService from "../services/apiServices";

const ForgetPassword = () => {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleEmailChange = (e) => {
    const { value } = e.target;
    setEmail(value);
    if (!value.trim()) {
      setError("");
    } else {
      setError("");
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!email.trim()) {
      setError("Email is required");
      return;
    }
    setLoading(true);
    setError("");
    try {
      const response = await apiService.sendPasswordResetEmail(email);
      console.log("Password reset email sent successfully:", response);
      // Display a success message
      setError("Your one-time login code has been sent to your email. Click the link in the email to reset your password.");
    } catch (error) {
      // Display custom error message based on the error type
      if (error.response && error.response.status === 404) {
        setError("Email not found. Please enter a valid email address.");
      } else {
        setError("An unexpected error occurred. Please try again later.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col items-center p-20 mt-10 shadow-sm max-w-[420px] max-h-[520px] text-blue-950 max-md:px-5" style={{ marginLeft: "780px" }}>
      <div className="mt-3 text-3xl font-semibold max-md:mt-10">EAII-PMS</div>
      <div className="mt-5 text-2xl font-semibold">Forgot Password</div>
      <div className="mt-5 text-base tracking-normal leading-6 text-justify text-zinc-500">
        Enter your email for the verification process, we will send a link to your email for changing your password.
      </div>
      <form onSubmit={handleSubmit}>
        <div className="mt-9 text-base text-slate-950">Email</div>
        <div className="flex flex-col">
          <input
            type="email"
            className="justify-center items-start px-4 py-5 mt-3 max-w-full text-sm whitespace-nowrap rounded-lg bg-zinc-100 text-slate-950 max-md:pr-5"
            value={email}
            onChange={handleEmailChange}
            placeholder="example@gmail.com"
            required
          />
          <button
            type="submit"
            className="mt-2 px bg-blue-500 text-white rounded-md hover:bg-blue-600 w-full ml-auto"
            disabled={loading}
          >
            {loading ? "Sending..." : "Continue"}
          </button>
        </div>
      </form>
      {error && <div className="text-red-500 -mt-24 ">{error}</div>}
    </div>
  );
};

export default ForgetPassword;
