import React, { useEffect, useState } from "react";
import Select from "react-select";
import Swal from "sweetalert2";
import apiService from "../services/apiServices";
import "./OrganizationalUnitModal.css";
const DivisionAdd = ({ handleCloseModal, handlefetchOrganizationalunit }) => {
  const [formData, setFormData] = useState({
    sector_id: "",
    head_id: "",
    name: "",
    // employee: "",
  });

  const [organizations, setOrganizations] = useState([]);
  const [users, setUsers] = useState([]);
  const handleChange = (selectedOption, name) => {
    setFormData({
      ...formData,
      [name]: selectedOption.value,
    });
  };
  const [userInfo, setUserInfo] = useState(() => {
    return JSON.parse(localStorage.getItem("userInfo")) || [];
  });
  const handleSubmit = async (e) => {
    e.preventDefault();
    console.log(formData);
    try {
      const response = await apiService.addorganizationalunit(formData);
      console.log(response);
      if (response.message === "New division created") {
        const Toast = Swal.mixin({
          toast: true,
          position: "top-end",
          showConfirmButton: false,
          timer: 1500,
          timerProgressBar: true,
          didOpen: (toast) => {
            toast.onmouseenter = Swal.stopTimer;
            toast.onmouseleave = Swal.resumeTimer;
          },
        });

        Toast.fire({
          icon: "success",
          title: "Department Added successfully",
        }).then(() => {
          handleCloseModal();
          handlefetchOrganizationalunit();
        });
      }
    } catch (error) {
      console.error("Error adding department:", error);
      Swal.fire({
        position: "center",
        icon: "error",
        title: "Failed to add Department",
        text: error.response.data.message,
        showConfirmButton: false,
        timer: 2500,
      });
    }
  };

  const handleCancel = () => {
    setFormData({
      name: "",
      head_id: "",
      sector_id: "",
    });
  };

  useEffect(() => {
    const fetchOrganizations = async () => {
      try {
        const organizationsData = await apiService.getallOrganizations(
          userInfo.access_token
        );
        const allEmployees = await apiService.getAllUsers(
          userInfo.access_token
        );
        console.log("Fetched organizations:", organizationsData);
        console.log("fetched all employees", allEmployees);
        setOrganizations(organizationsData);
        setUsers(allEmployees);
      } catch (error) {
        console.error("Error fetching organizations:", error);
      }
    };
    async function fetchUsers() {
      localStorage.setItem("userInfo", JSON.stringify(userInfo));
    }
    fetchUsers();

    fetchOrganizations();
  }, []);
  return (
    <div className="ml-10">
      <div className="add-div-title">Add Department</div>
      <form onSubmit={handleSubmit}>
        <div className="form-row">
          <div className="form-group">
            <label htmlFor="division_name" className="required">
              Department Name
            </label>
            <input
              type="text"
              id="division_name"
              name="division_name"
              //   className="inputf"
              value={formData.name}
              className="pl-4 w-80 h-14"
              placeholder="Enter Department Name"
              required
              onChange={(e) =>
                setFormData({ ...formData, name: e.target.value })
              }
            />
          </div>
          <div className="form-group">
            <label htmlFor="leader">Leader</label>

            <Select
              name="leader"
              className="w-80"
              value={{
                value: formData.head_id,
                label:
                  users.find((user) => user.user_id === formData.head_id)
                    ?.full_name || "",
              }}
              required
              onChange={(selectedOption) =>
                handleChange(selectedOption, "head_id")
              }
              options={users.map((user) => ({
                value: user.user_id,
                label: user.full_name,
              }))}
            />
          </div>
        </div>

        <div className="form-row">
          <div className="form-group ">
            <label htmlFor="leader" className="required">
              Sector
            </label>
            {/* <Select
              id="sector"
              name="sector"
              className="w-80"
              value={formData.sector}
              required
              style={{
                color: formData.sector ? "black" : "gray",
              }}
              onChange={(e) =>
                setFormData({ ...formData, sector: e.target.value })
              }
            >
              <option value="" disabled hidden>
                Select Organization
              </option>
              {organizations.map((organization) => (
                <option
                  key={organization.sector_id}
                  value={organization.sector_id}
                >
                  {organization.name}
                </option>
              ))}
            </Select> */}
            <Select
              name="leader"
              className="w-80"
              value={{
                value: formData.sector_id,
                label:
                  organizations.find(
                    (organization) =>
                      organization.sector.sector_id === formData.sector_id
                  )?.sector.name || "",
              }}
              required
              onChange={(selectedOption) =>
                handleChange(selectedOption, "sector_id")
              }
              options={organizations.map((organization) => ({
                value: organization.sector.sector_id,
                label: organization.sector.name,
              }))}
            />
          </div>
          {/* <div className="">
            <label htmlFor="employee">Employee</label>
            <Select
              id="employee"
              name="employee"
              className="sec-employee w-80"
              value={formData.employee}
              style={{
                color: formData.employee ? "black" : "gray",
                paddingLeft: "1vw",
              }}
              onChange={(e) =>
                setFormData({ ...formData, employee: e.target.value })
              }
            >
              <option value="" disabled hidden>
                Select Employee
              </option>
              {employees.map((employee) => (
                <option key={employee.user_id} value={employee.user_id}>
                  {employee.full_name}
                </option>
              ))}
            </Select>
          </div> */}
        </div>

        <div className="flex justify-end gap-4 -mt-16 mb-10 mr-44">
          <button onClick={handleCancel}>Cancel</button>
          <button
            className="text-white font-bold py-2 px-4 rounded"
            style={{ backgroundColor: "#082f49" }}
          >
            Add Department
          </button>
        </div>
      </form>
    </div>
  );
};

export default DivisionAdd;
