import React, { useState } from "react";
import Swal from "sweetalert2";
import { useAuth } from "../../context/authContext";
import ProfilePicIcon from "../Assets/mypp.png";
import "./Myprofile.css";
import "./Registernewuser.css";

const Myprofile = () => {
  const [showCurrentPassword, setShowCurrentPassword] = useState(false);
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const auth = useAuth();
  console.log(auth.userInfo.foundUser.full_name);

  const togglePasswordVisibility = (field) => {
    switch (field) {
      case "currentPassword":
        setShowCurrentPassword(!showCurrentPassword);
        break;
      case "newPassword":
        setShowNewPassword(!showNewPassword);
        break;
      case "confirmPassword":
        setShowConfirmPassword(!showConfirmPassword);
        break;
      default:
        break;
    }
  };
  const handleSaveChanges = () => {
    const Toast = Swal.mixin({
      toast: true,
      position: "top-end",
      showConfirmButton: false,
      timer: 3000,
      timerProgressBar: true,
      didOpen: (toast) => {
        toast.onmouseenter = Swal.stopTimer;
        toast.onmouseleave = Swal.resumeTimer;
      },
    });
    Toast.fire({
      icon: "success",
      title: "Profile Updated successfully",
    });
  };
  return (
    <div className="myy-profilee-container">
      <p className="titleprofile">My Profile</p>
      <div className="profile-container">
        <div className="profilee-picture">
          <img src={ProfilePicIcon} alt="Profile" />{" "}
        </div>
        <button className="edit-button">Edit profile</button>
      </div>
      <div className="nameandemail">
        <div className="form-ggroup">
          <label htmlFor="fullName" className="required">
            Full Name
          </label>
          <input
            type="text"
            id="fullName"
            name="fullName"
            className="inpu"
            placeholder="Enter Full Name"
            value={auth.userInfo.foundUser.full_name}
            required
          />
        </div>
        <div className="form-ggroup">
          <label htmlFor="email" className="required">
            Email
          </label>
          <input
            type="email"
            id="email"
            name="email"
            className="inpu"
            placeholder="example@example.com"
            value={auth.userInfo.foundUser.email}
            required
          />
        </div>
      </div>
      <div className="border1"></div>

      <div className="border"></div>
      <div className="comp2">
        <div className="formmm-row">
          <div className="formmm-group">
            <label htmlFor="currentPassword" className="required">
              Current Password
            </label>
            <div className="password-input">
              <input
                className="inpu"
                type={showCurrentPassword ? "text" : "password"}
                id="currentPassword"
                name="currentPassword"
                placeholder="Enter current password"
              />
              <i
                className={`password-toggle-icon ${
                  showCurrentPassword ? "visible" : "hidden"
                }`}
                onClick={() => togglePasswordVisibility("currentPassword")}
              ></i>
            </div>
          </div>
          <div className="formmm-group">
            <label htmlFor="newPassword" className="required">
              New Password
            </label>
            <div className="password-input">
              <input
                className="inpu"
                type={showNewPassword ? "text" : "password"}
                id="newPassword"
                name="newPassword"
                placeholder="Enter new password"
              />
              <i
                className={`password-toggle-icon ${
                  showNewPassword ? "visible" : "hidden"
                }`}
                onClick={() => togglePasswordVisibility("newPassword")}
              ></i>
            </div>
          </div>
        </div>

        <div className="formmm-row">
          <label htmlFor="confirmPassword" className="required">
            Confirm New Password
          </label>
          <div className="password-input">
            <input
              type={showConfirmPassword ? "text" : "password"}
              id="confirmPassword"
              className="inpu"
              name="confirmPassword"
              placeholder="Re-enter new password"
            />
            <i
              className={`password-toggle-icon ${
                showConfirmPassword ? "visible" : "hidden"
              }`}
              onClick={() => togglePasswordVisibility("confirmPassword")}
            ></i>
          </div>
        </div>
        <div className="formm-buttonss">
          <button type="button">Cancel</button>

          <button
            className="text-white font-bold py-2 px-4 rounded"
            onClick={handleSaveChanges}
            type="submit"
            style={{ backgroundColor: "#082f49" }}
          >
            Save Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default Myprofile;
